-- Artificer (artificer)
update public.custom_classes
   set data = $persona_content_migration${"ui":{},"name":"Artificer","index":"artificer","rules":[],"caster":{"type":"artificer","ability":"int"},"source":"Eberron: Rising from the Last War","choices":[{"id":"artificer-proficiency-0","kind":"proficiency","count":2,"source":"class","options":[{"name":"Arcana","index":"arcana","category":"skill","rawName":"Skill: Arcana"},{"name":"History","index":"history","category":"skill","rawName":"Skill: History"},{"name":"Investigation","index":"investigation","category":"skill","rawName":"Skill: Investigation"},{"name":"Medicine","index":"medicine","category":"skill","rawName":"Skill: Medicine"},{"name":"Nature","index":"nature","category":"skill","rawName":"Skill: Nature"},{"name":"Perception","index":"perception","category":"skill","rawName":"Skill: Perception"},{"name":"Sleight of Hand","index":"sleight-of-hand","category":"skill","rawName":"Skill: Sleight of Hand"}]}],"hit_die":8,"resources":[{"key":"flash-of-genius","max":{"min":1,"type":"ability","ability":"int"},"name":"Flash of Genius","level":7,"reset":"long","source":"Artificer"}],"spell_list":["artificer"],"level_table":[{"level":1,"features":["Magical Tinkering","Spellcasting"],"prof_bonus":2,"class_specific":{"cantrips":2,"infused_items":0,"infusions_known":0}},{"level":2,"features":["Infuse Item"],"prof_bonus":2,"class_specific":{"cantrips":2,"infused_items":2,"infusions_known":3}},{"level":3,"features":["Artificer Specialist","The Right Tool for the Job"],"prof_bonus":2,"class_specific":{"cantrips":2,"infused_items":2,"infusions_known":3}},{"level":4,"features":["Ability Score Improvement"],"prof_bonus":2,"class_specific":{"cantrips":2,"infused_items":2,"infusions_known":4}},{"level":5,"features":["Specialist Feature"],"prof_bonus":3,"class_specific":{"cantrips":2,"infused_items":2,"infusions_known":4}},{"level":6,"features":["Tool Expertise"],"prof_bonus":3,"class_specific":{"cantrips":2,"infused_items":3,"infusions_known":4}},{"level":7,"features":["Flash of Genius"],"prof_bonus":3,"class_specific":{"cantrips":2,"infused_items":3,"infusions_known":5}},{"level":8,"features":["Ability Score Improvement"],"prof_bonus":3,"class_specific":{"cantrips":2,"infused_items":3,"infusions_known":5}},{"level":9,"features":["Specialist Feature"],"prof_bonus":4,"class_specific":{"cantrips":2,"infused_items":3,"infusions_known":5}},{"level":10,"features":["Magic Item Adept"],"prof_bonus":4,"class_specific":{"cantrips":3,"infused_items":3,"infusions_known":5}},{"level":11,"features":["Spell-Storing Item"],"prof_bonus":4,"class_specific":{"cantrips":3,"infused_items":4,"infusions_known":6}},{"level":12,"features":["Ability Score Improvement"],"prof_bonus":4,"class_specific":{"cantrips":3,"infused_items":4,"infusions_known":6}},{"level":13,"features":[],"prof_bonus":5,"class_specific":{"cantrips":3,"infused_items":4,"infusions_known":6}},{"level":14,"features":["Magic Item Savant"],"prof_bonus":5,"class_specific":{"cantrips":4,"infused_items":4,"infusions_known":6}},{"level":15,"features":["Specialist Feature"],"prof_bonus":5,"class_specific":{"cantrips":4,"infused_items":4,"infusions_known":7}},{"level":16,"features":["Ability Score Improvement"],"prof_bonus":5,"class_specific":{"cantrips":4,"infused_items":5,"infusions_known":7}},{"level":17,"features":[],"prof_bonus":6,"class_specific":{"cantrips":4,"infused_items":5,"infusions_known":7}},{"level":18,"features":["Magic Item Master"],"prof_bonus":6,"class_specific":{"cantrips":4,"infused_items":5,"infusions_known":7}},{"level":19,"features":["Ability Score Improvement"],"prof_bonus":6,"class_specific":{"cantrips":4,"infused_items":5,"infusions_known":8}},{"level":20,"features":["Soul of Artifice"],"prof_bonus":6,"class_specific":{"cantrips":4,"infused_items":5,"infusions_known":8}}],"spellcasting":{"info":[],"level":1,"progression":"artificer","spellcasting_ability":{"url":"","name":"Intelligence","index":"int"}},"proficiencies":[{"url":"","name":"Light Armor","index":"light-armor"},{"url":"","name":"Medium Armor","index":"medium-armor"},{"url":"","name":"Shields","index":"shields"},{"url":"","name":"Simple Weapons","index":"simple-weapons"},{"url":"","name":"Hand Crossbow","index":"hand-crossbow"},{"url":"","name":"Heavy Crossbow","index":"heavy-crossbow"},{"url":"","name":"Thieves' Tools","index":"thieves-tools"},{"url":"","name":"Tinker's Tools","index":"tinkers-tools"}],"saving_throws":[{"url":"","name":"CON","index":"con"},{"url":"","name":"INT","index":"int"}],"schema_version":2,"subclass_label":"Artificer Specialist","subclass_level":3,"feature_details":[{"url":"","desc":["You learn how to invest a spark of magic in objects that would otherwise be mundane. Using thieves' tools or artisan's tools, you can touch a Tiny nonmagical object as an action and give it a magical property: shedding light, emitting a sound/odor, showing a visual effect, or recording a message. You can affect a number of objects equal to your Intelligence modifier."],"name":"Magical Tinkering","index":"magical-tinkering","level":1,"source":"Artificer","effects":[]},{"url":"","desc":["You have studied the workings of magic and how to channel it through objects. You use Intelligence as your spellcasting ability and must use a tool you are proficient with as a spellcasting focus."],"name":"Spellcasting","index":"spellcasting-artificer","level":1,"source":"Artificer","effects":[]},{"url":"","desc":["You gain the ability to imbue mundane items with magical infusions. You learn a number of infusions and can have a maximum number of items infused at once based on your level. Whenever you finish a long rest, you can touch a nonmagical object and imbue it with one of your infusions, turning it into a magic item."],"name":"Infuse Item","index":"infuse-item","level":2,"source":"Artificer","effects":[{"name":"Infuse Item","type":"action","description":"Imbue an item with a magical infusion."}]},{"url":"","desc":["You choose the type of specialist you are: Alchemist, Artillerist, or Battle Smith. Your choice grants you features at 3rd, 5th, 9th, and 15th levels."],"name":"Artificer Specialist","index":"artificer-specialist","level":3,"source":"Artificer","effects":[]},{"url":"","desc":["You can magically create one set of artisan's tools in an unoccupied space within 5 feet of you using tinker's tools and 1 hour of work."],"name":"The Right Tool for the Job","index":"the-right-tool-for-the-job","level":3,"source":"Artificer","effects":[]},{"url":"","desc":["Your proficiency bonus is doubled for any ability check you make that uses your proficiency with a tool."],"name":"Tool Expertise","index":"tool-expertise","level":6,"source":"Artificer","effects":[]},{"url":"","desc":["When you or another creature you can see within 30 feet makes an ability check or saving throw, you can use your reaction to add your Intelligence modifier to the roll. You can use this a number of times equal to your Intelligence modifier (min 1) per Long Rest."],"name":"Flash of Genius","index":"flash-of-genius","level":7,"source":"Artificer","effects":[{"name":"Flash of Genius","type":"reaction","description":"Add your Intelligence modifier to an ability check or saving throw."}]},{"url":"","desc":["You can attune to up to four magic items at once. If you craft a magic item with a rarity of common or uncommon, it takes you a quarter of the normal time and costs half as much gold."],"name":"Magic Item Adept","index":"magic-item-adept","level":10,"source":"Artificer","effects":[]},{"url":"","desc":["You can store a 1st- or 2nd-level artificer spell in a weapon or focus. A creature holding the object can use an action to cast the spell using your spellcasting ability modifier. It can be used a number of times equal to twice your Intelligence modifier."],"name":"Spell-Storing Item","index":"spell-storing-item","level":11,"source":"Artificer","effects":[]},{"url":"","desc":["You can attune to up to five magic items at once. You ignore all class, race, spell, and level requirements on attuning to or using a magic item."],"name":"Magic Item Savant","index":"magic-item-savant","level":14,"source":"Artificer","effects":[]},{"url":"","desc":["You can attune to up to six magic items at once."],"name":"Magic Item Master","index":"magic-item-master","level":18,"source":"Artificer","effects":[]},{"url":"","desc":["You gain a +1 bonus to all saving throws per magic item you are currently attuned to. If you drop to 0 HP, you can use your reaction to end one infusion and drop to 1 HP instead."],"name":"Soul of Artifice","index":"soul-of-artifice","level":20,"source":"Artificer","effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Arcana","index":"arcana"}},{"item":{"url":"","name":"Skill: History","index":"history"}},{"item":{"url":"","name":"Skill: Investigation","index":"investigation"}},{"item":{"url":"","name":"Skill: Medicine","index":"medicine"}},{"item":{"url":"","name":"Skill: Nature","index":"nature"}},{"item":{"url":"","name":"Skill: Perception","index":"perception"}},{"item":{"url":"","name":"Skill: Sleight of Hand","index":"sleight-of-hand"}}]},"type":"proficiencies","choose":2}]}$persona_content_migration$::jsonb,
