 where id = 'e753bef6-f307-4c61-ae88-d788f7bc5e75';

-- Paladin (paladin)
update public.custom_classes
   set data = $persona_content_migration${"ui":{},"name":"Paladin","index":"paladin","rules":[],"caster":{"type":"half","ability":"cha"},"source":"Player's Handbook 2024","choices":[{"id":"paladin-proficiency-0","kind":"proficiency","count":2,"source":"class","options":[{"name":"Athletics","index":"athletics","category":"skill","rawName":"Skill: Athletics"},{"name":"Insight","index":"insight","category":"skill","rawName":"Skill: Insight"},{"name":"Intimidation","index":"intimidation","category":"skill","rawName":"Skill: Intimidation"},{"name":"Medicine","index":"medicine","category":"skill","rawName":"Skill: Medicine"},{"name":"Persuasion","index":"persuasion","category":"skill","rawName":"Skill: Persuasion"},{"name":"Religion","index":"religion","category":"skill","rawName":"Skill: Religion"}]}],"hit_die":10,"resources":[{"key":"lay-on-hands","max":{"type":"level","multiplier":5},"name":"Lay on Hands","level":1,"reset":"long","source":"Paladin"},{"key":"channel-divinity","max":{"type":"table","values":[0,0,2,2,2,2,2,2,2,2,3,3,3,3,3,3,3,3,3,3]},"name":"Channel Divinity","level":3,"reset":"short","source":"Paladin"}],"spell_list":["paladin"],"level_table":[{"level":1,"features":["Lay on Hands","Spellcasting","Weapon Mastery"],"prof_bonus":2,"class_specific":{"cd_uses":0,"prepared":2}},{"level":2,"features":["Fighting Style","Paladin's Smite"],"prof_bonus":2,"class_specific":{"cd_uses":0,"prepared":3}},{"level":3,"features":["Channel Divinity","Paladin Subclass"],"prof_bonus":2,"class_specific":{"cd_uses":2,"prepared":4}},{"level":4,"features":["Ability Score Improvement"],"prof_bonus":2,"class_specific":{"cd_uses":2,"prepared":5}},{"level":5,"features":["Extra Attack","Faithful Steed"],"prof_bonus":3,"class_specific":{"cd_uses":2,"prepared":6}},{"level":6,"features":["Aura of Protection"],"prof_bonus":3,"class_specific":{"cd_uses":2,"prepared":6}},{"level":7,"features":["Subclass feature"],"prof_bonus":3,"class_specific":{"cd_uses":2,"prepared":7}},{"level":8,"features":["Ability Score Improvement"],"prof_bonus":3,"class_specific":{"cd_uses":2,"prepared":7}},{"level":9,"features":["Abjure Foes"],"prof_bonus":4,"class_specific":{"cd_uses":2,"prepared":9}},{"level":10,"features":["Aura of Courage"],"prof_bonus":4,"class_specific":{"cd_uses":2,"prepared":9}},{"level":11,"features":["Radiant Strikes"],"prof_bonus":4,"class_specific":{"cd_uses":3,"prepared":10}},{"level":12,"features":["Ability Score Improvement"],"prof_bonus":4,"class_specific":{"cd_uses":3,"prepared":10}},{"level":13,"features":[],"prof_bonus":5,"class_specific":{"cd_uses":3,"prepared":11}},{"level":14,"features":["Restoring Touch"],"prof_bonus":5,"class_specific":{"cd_uses":3,"prepared":11}},{"level":15,"features":["Subclass feature"],"prof_bonus":5,"class_specific":{"cd_uses":3,"prepared":12}},{"level":16,"features":["Ability Score Improvement"],"prof_bonus":5,"class_specific":{"cd_uses":3,"prepared":12}},{"level":17,"features":[],"prof_bonus":6,"class_specific":{"cd_uses":3,"prepared":14}},{"level":18,"features":["Aura Expansion"],"prof_bonus":6,"class_specific":{"cd_uses":3,"prepared":14}},{"level":19,"features":["Epic Boon"],"prof_bonus":6,"class_specific":{"cd_uses":3,"prepared":15}},{"level":20,"features":["Subclass feature"],"prof_bonus":6,"class_specific":{"cd_uses":3,"prepared":15}}],"spellcasting":{"info":[],"level":1,"progression":"half","spellcasting_ability":{"url":"","name":"Charisma","index":"cha"}},"proficiencies":[{"url":"","name":"All Armor","index":"all-armor"},{"url":"","name":"Shields","index":"shields"},{"url":"","name":"Simple Weapons","index":"simple-weapons"},{"url":"","name":"Martial Weapons","index":"martial-weapons"}],"saving_throws":[{"url":"","name":"WIS","index":"wis"},{"url":"","name":"CHA","index":"cha"}],"schema_version":2,"subclass_label":"Sacred Oath","subclass_level":3,"feature_details":[{"url":"","desc":["Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you take a long rest. With that pool, you can restore a total number of hit points equal to your paladin level × 5. As a Bonus Action, you can touch a creature and draw power from the pool to restore a number of hit points to that creature, up to the maximum amount remaining in your pool."],"name":"Lay on Hands","index":"lay-on-hands-2024","level":1,"source":"Paladin","effects":[{"name":"Lay on Hands","type":"action","description":"Restore a pool of hit points equal to five times your Paladin level."}]},{"url":"","desc":["You have learned to draw on divine magic through meditation and prayer to cast spells. You prepare a list of spells from the Paladin list."],"name":"Spellcasting","index":"spellcasting-paladin-2024","level":1,"source":"Paladin","effects":[]},{"url":"","desc":["Your training with weapons allows you to use the mastery properties of specific kinds of weapons. You can choose a number of weapon types to master based on your level."],"name":"Weapon Mastery","index":"weapon-mastery-paladin","level":1,"source":"Paladin","effects":[]},{"url":"","desc":["You adopt a particular style of fighting as your specialty."],"name":"Fighting Style","index":"fighting-style-paladin","level":2,"source":"Paladin","effects":[{"name":"Fighting Style","type":"feature_choice","count":1,"options":[{"desc":"You gain a +2 bonus to Attack Rolls you make with Ranged Weapons.","name":"Archery","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":2}]},{"desc":"While you are wearing armor, you gain a +1 bonus to AC.","name":"Defense","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.","name":"Dueling","effects":[{"stat":"weapon_damage","type":"stat_bonus","value":2}]},{"desc":"When you roll a 1 or 2 on a damage die for an attack you make with a melee weapon that you are wielding with two hands, you can reroll the die and must use the new roll.","name":"Great Weapon Fighting"},{"desc":"When a creature you can see attacks a target other than you that is within 5 feet of you, you can use your reaction to impose disadvantage on the attack roll. You must be wielding a shield.","name":"Protection"},{"desc":"As long as you are not wearing armor or using a shield, you have a swimming speed and a climbing speed equal to your normal speed, and you gain a +1 bonus to AC.","name":"Mariner","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"You are trained in making ranged attacks at close quarters. When making a ranged attack while you are within 5 feet of a hostile creature, you do not have disadvantage on the attack roll. Your ranged attacks ignore half cover and three-quarter cover against targets within 30 feet of you. Finally, you have a +1 bonus to attack rolls on ranged attacks.","name":"Close Quarters Shooter","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":1}]},{"desc":"When a teammate misses an opportunity attack against an enemy you can see, you can use your reaction to make an opportunity attack against the same target, as long as they are in range.","name":"Opportune Ranger"}]}]},{"url":"","desc":["You always have the Divine Smite spell prepared. In addition, you can cast it or another Smite spell as a Bonus Action immediately after hitting a target with an attack roll."],"name":"Paladin's Smite","index":"paladins-smite","level":2,"source":"Paladin","effects":[{"name":"Paladin's Smite","type":"bonus_action","description":"Cast a smite spell as a bonus action."},{"name":"Divine Smite","type":"attack_rider","condition":"melee_weapon","description":"When you hit a creature with a melee weapon attack, you can expend one spell slot to deal extra radiant damage."}]},{"url":"","desc":["You gain the ability to channel divine energy directly from your deity, using that energy to fuel various magical effects. You start with two such effects: Divine Sense and an option granted by your subclass."],"name":"Channel Divinity","index":"channel-divinity-paladin","level":3,"source":"Paladin","effects":[{"name":"Channel Divinity","type":"action","description":"Channel divine energy to produce a magical effect."}]},{"url":"","desc":["Choose an oath that binds you to a particular set of tenets."],"name":"Paladin Subclass","index":"paladin-subclass-2024","level":3,"source":"Paladin","effects":[]},{"url":"","desc":["You can attack twice, instead of once, whenever you take the Attack action on your turn."],"name":"Extra Attack","index":"extra-attack-paladin","level":5,"source":"Paladin","effects":[{"mode":"set","name":"Extra Attack","type":"extra_attack","value":2}]},{"url":"","desc":["You can cast the Find Steed spell without expending a spell slot. You can do so once per Long Rest."],"name":"Faithful Steed","index":"faithful-steed","level":5,"source":"Paladin","effects":[]},{"url":"","desc":["Whenever you or a friendly creature within 10 feet of you must make a saving throw, the creature gains a bonus to the saving throw equal to your Charisma modifier (with a minimum bonus of +1). You must be conscious to grant this bonus."],"name":"Aura of Protection","index":"aura-of-protection","level":6,"source":"Paladin","effects":[{"name":"Aura of Protection","type":"bonus","value":{"min":1,"type":"ability","ability":"cha"},"target":"saves","condition":"within_10ft"}]},{"url":"","desc":["As an action, you can expend one use of your Channel Divinity to force each creature of your choice within 30 feet to make a Wisdom save. On a failure, a creature is Frightened for 1 minute or until it takes damage."],"name":"Abjure Foes","index":"abjure-foes","level":9,"source":"Paladin","effects":[]},{"url":"","desc":["You and friendly creatures within 10 feet of you can't be frightened while you are conscious."],"name":"Aura of Courage","index":"aura-of-courage","level":10,"source":"Paladin","effects":[]},{"url":"","desc":["You are so suffused with righteous might that all your melee weapon strikes carry divine power with them. Whenever you hit a creature with a melee weapon, the creature takes an extra 1d8 radiant damage."],"name":"Radiant Strikes","index":"radiant-strikes","level":11,"source":"Paladin","effects":[{"name":"Radiant Strikes","type":"attack_rider","level":11,"damage":"1d8","condition":"melee_weapon","damage_type":"Radiant"}]},{"url":"","desc":["When you use your Lay on Hands on a creature, you can also end one or more of the following conditions on it: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned."],"name":"Restoring Touch","index":"restoring-touch","level":14,"source":"Paladin","effects":[]},{"url":"","desc":["The range of your Aura of Protection and Aura of Courage (and other subclass auras) increases to 30 feet."],"name":"Aura Expansion","index":"aura-expansion","level":18,"source":"Paladin","effects":[]},{"url":"","desc":["You gain an Epic Boon feat of your choice."],"name":"Epic Boon","index":"epic-boon-paladin","level":19,"source":"Paladin","effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Athletics","index":"athletics"}},{"item":{"url":"","name":"Skill: Insight","index":"insight"}},{"item":{"url":"","name":"Skill: Intimidation","index":"intimidation"}},{"item":{"url":"","name":"Skill: Medicine","index":"medicine"}},{"item":{"url":"","name":"Skill: Persuasion","index":"persuasion"}},{"item":{"url":"","name":"Skill: Religion","index":"religion"}}]},"type":"proficiencies","choose":2}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'paladin'),
       source = 'Player''s Handbook 2024',
       migrated_at = now()
 where id = '3a160ea5-ef4a-48d2-b365-5b44a0fe87b7';

