l":"","name":"STR","index":"str"},{"url":"","name":"DEX","index":"dex"}],"schema_version":2,"subclass_label":"Ranger Archetype","subclass_level":3,"feature_details":[{"url":"","desc":["You have learned to use the magical essence of nature to cast spells. You prepare a list of spells from the Ranger list."],"name":"Spellcasting","index":"spellcasting-ranger-2024","level":1,"source":"Ranger","effects":[]},{"url":"","desc":["You always have the Hunter's Mark spell prepared. You can cast it without expending a spell slot a number of times equal to your Proficiency Bonus."],"name":"Favored Enemy","index":"favored-enemy-2024","level":1,"source":"Ranger","effects":[]},{"url":"","desc":["Your training with weapons allows you to use the mastery properties of specific kinds of weapons. You can choose a number of weapon types to master based on your level."],"name":"Weapon Mastery","index":"weapon-mastery-ranger","level":1,"source":"Ranger","effects":[]},{"url":"","desc":["You are an unsurpassed explorer. You gain the Canny benefit now, and you gain the Roving and Tireless benefits at later levels. Canny: Expertise in one skill and two languages."],"name":"Deft Explorer","index":"deft-explorer","level":2,"source":"Ranger","effects":[{"type":"expertise_choice","count":1,"category":"skill"}]},{"url":"","desc":["You adopt a particular style of fighting as your specialty."],"name":"Fighting Style","index":"fighting-style-ranger","level":2,"source":"Ranger","effects":[{"name":"Fighting Style","type":"feature_choice","count":1,"options":[{"desc":"You gain a +2 bonus to Attack Rolls you make with Ranged Weapons.","name":"Archery","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":2}]},{"desc":"While you are wearing armor, you gain a +1 bonus to AC.","name":"Defense","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.","name":"Dueling","effects":[{"stat":"weapon_damage","type":"stat_bonus","value":2}]},{"desc":"When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.","name":"Two-Weapon Fighting"},{"desc":"As long as you are not wearing armor or using a shield, you have a swimming speed and a climbing speed equal to your normal speed, and you gain a +1 bonus to AC.","name":"Mariner","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"You are trained in making ranged attacks at close quarters. When making a ranged attack while you are within 5 feet of a hostile creature, you do not have disadvantage on the attack roll. Your ranged attacks ignore half cover and three-quarter cover against targets within 30 feet of you. Finally, you have a +1 bonus to attack rolls on ranged attacks.","name":"Close Quarters Shooter","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":1}]},{"desc":"When a teammate misses an opportunity attack against an enemy you can see, you can use your reaction to make an opportunity attack against the same target, as long as they are in range.","name":"Opportune Ranger"}]}]},{"url":"","desc":["You can attack twice, instead of once, whenever you take the Attack action on your turn."],"name":"Extra Attack","index":"extra-attack-ranger","level":5,"source":"Ranger","effects":[{"mode":"set","name":"Extra Attack","type":"extra_attack","value":2}]},{"url":"","desc":["Your walking speed increases by 5 feet. You also gain a climbing speed and a swimming speed equal to your walking speed."],"name":"Roving","index":"roving","level":6,"source":"Ranger","effects":[{"name":"Roving","stat":"speed","type":"stat_bonus","value":10,"condition":"not_heavy_armor"}]},{"url":"","desc":["Choose two of your skill proficiencies. Your proficiency bonus is doubled for these choices."],"name":"Expertise","index":"expertise-ranger","level":9,"source":"Ranger","effects":[{"type":"expertise_choice","count":2,"category":"skill"}]},{"url":"","desc":["As an action, you can give yourself temporary hit points (1d8 + Wisdom modifier) a number of times equal to your Proficiency Bonus per Long Rest. In addition, when you finish a Short Rest, your exhaustion level, if any, is decreased by 1."],"name":"Tireless","index":"tireless","level":10,"source":"Ranger","effects":[{"name":"Tireless","type":"action","description":"Gain temporary hit points and reduce exhaustion."}]},{"url":"","desc":["Taking damage can't break your concentration on Hunter's Mark."],"name":"Relentless Hunter","index":"relentless-hunter","level":13,"source":"Ranger","effects":[]},{"url":"","desc":["You can draw on the powers of nature to hide yourself. As a Bonus Action, you can magically become invisible, along with any equipment you are wearing or carrying, until the end of your next turn. (PB/Long Rest)"],"name":"Nature's Veil","index":"natures-veil","level":14,"source":"Ranger","effects":[{"name":"Nature's Veil","type":"bonus_action","description":"Become invisible until the end of your next turn."}]},{"url":"","desc":["You have advantage on attack rolls against the creature currently marked by your Hunter's Mark spell."],"name":"Precise Hunter","index":"precise-hunter","level":17,"source":"Ranger","effects":[]},{"url":"","desc":["You gain blindsight out to a range of 30 feet."],"name":"Feral Senses","index":"feral-senses","level":18,"source":"Ranger","effects":[]},{"url":"","desc":["Your marks are particularly deadly. You can add your Wisdom modifier to the damage roll of your attacks against a creature marked by Hunter's Mark, and you can add it to the attack roll as well."],"name":"Foe Slayer","index":"foe-slayer","level":20,"source":"Ranger","effects":[{"name":"Foe Slayer","type":"feature","description":"Add your Wisdom modifier to an attack or damage roll against a favored enemy."},{"name":"Foe Slayer","type":"attack_rider","condition":"weapon","description":"You can add your Wisdom modifier to the attack roll or the damage roll of an attack you make against one of your favored enemies."}]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Animal Handling","index":"animal-handling"}},{"item":{"url":"","name":"Skill: Athletics","index":"athletics"}},{"item":{"url":"","name":"Skill: Insight","index":"insight"}},{"item":{"url":"","name":"Skill: Investigation","index":"investigation"}},{"item":{"url":"","name":"Skill: Nature","index":"nature"}},{"item":{"url":"","name":"Skill: Perception","index":"perception"}},{"item":{"url":"","name":"Skill: Stealth","index":"stealth"}},{"item":{"url":"","name":"Skill: Survival","index":"survival"}}]},"type":"proficiencies","choose":3}]}$persona_content_migration$::jsonb,
