update public.custom_classes
   set data = $persona_content_migration${"ui":{},"name":"Cleric","index":"cleric","rules":[],"caster":{"type":"full","ability":"wis"},"source":"Player's Handbook 2024","choices":[{"id":"cleric-proficiency-0","kind":"proficiency","count":2,"source":"class","options":[{"name":"History","index":"history","category":"skill","rawName":"Skill: History"},{"name":"Insight","index":"insight","category":"skill","rawName":"Skill: Insight"},{"name":"Medicine","index":"medicine","category":"skill","rawName":"Skill: Medicine"},{"name":"Persuasion","index":"persuasion","category":"skill","rawName":"Skill: Persuasion"},{"name":"Religion","index":"religion","category":"skill","rawName":"Skill: Religion"}]}],"hit_die":8,"resources":[{"key":"channel-divinity","max":{"type":"table","values":[0,2,2,2,2,3,3,3,3,3,3,3,3,3,3,3,3,4,4,4]},"name":"Channel Divinity","level":2,"reset":"short","source":"Cleric"}],"spell_list":["cleric"],"level_table":[{"level":1,"features":["Spellcasting","Divine Order"],"prof_bonus":2,"class_specific":{"cantrips":3,"prepared":4}},{"level":2,"features":["Channel Divinity"],"prof_bonus":2,"class_specific":{"cd_uses":2,"cantrips":3,"prepared":5}},{"level":3,"features":["Divine Domain"],"prof_bonus":2,"class_specific":{"cd_uses":2,"cantrips":3,"prepared":6}},{"level":4,"features":["Ability Score Improvement"],"prof_bonus":2,"class_specific":{"cd_uses":2,"cantrips":4,"prepared":7}},{"level":5,"features":["Sear Undead"],"prof_bonus":3,"class_specific":{"cd_uses":2,"cantrips":4,"prepared":9}},{"level":6,"features":["Subclass Feature"],"prof_bonus":3,"class_specific":{"cd_uses":3,"cantrips":4,"prepared":10}},{"level":7,"features":["Blessed Strikes"],"prof_bonus":3,"class_specific":{"cd_uses":3,"cantrips":4,"prepared":11}},{"level":8,"features":["Ability Score Improvement"],"prof_bonus":3,"class_specific":{"cd_uses":3,"cantrips":4,"prepared":12}},{"level":9,"features":[],"prof_bonus":4,"class_specific":{"cd_uses":3,"cantrips":4,"prepared":14}},{"level":10,"features":["Divine Intervention"],"prof_bonus":4,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":15}},{"level":11,"features":[],"prof_bonus":4,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":16}},{"level":12,"features":["Ability Score Improvement"],"prof_bonus":4,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":16}},{"level":13,"features":[],"prof_bonus":5,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":17}},{"level":14,"features":["Improved Blessed Strikes"],"prof_bonus":5,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":17}},{"level":15,"features":[],"prof_bonus":5,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":18}},{"level":16,"features":["Ability Score Improvement"],"prof_bonus":5,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":18}},{"level":17,"features":["Subclass Feature"],"prof_bonus":6,"class_specific":{"cd_uses":3,"cantrips":5,"prepared":19}},{"level":18,"features":[],"prof_bonus":6,"class_specific":{"cd_uses":4,"cantrips":5,"prepared":20}},{"level":19,"features":["Epic Boon"],"prof_bonus":6,"class_specific":{"cd_uses":4,"cantrips":5,"prepared":21}},{"level":20,"features":["Greater Divine Intervention"],"prof_bonus":6,"class_specific":{"cd_uses":4,"cantrips":5,"prepared":22}}],"spellcasting":{"info":[],"level":1,"progression":"full","spellcasting_ability":{"url":"","name":"Wisdom","index":"wis"}},"proficiencies":[{"url":"","name":"Light Armor","index":"light-armor"},{"url":"","name":"Medium Armor","index":"medium-armor"},{"url":"","name":"Shields","index":"shields"},{"url":"","name":"Simple Weapons","index":"simple-weapons"}],"saving_throws":[{"url":"","name":"WIS","index":"wis"},{"url":"","name":"CHA","index":"cha"}],"schema_version":2,"subclass_label":"Divine Domain","subclass_level":1,"feature_details":[{"url":"","desc":["You have learned to cast spells through prayer and meditation.","**Cantrips:** You know three cantrips of your choice from the Cleric spell list. Whenever you gain a Cleric level, you can replace one of your cantrips with another cantrip of your choice from the Cleric spell list.","**Spell Slots:** The Cleric Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.","**Prepared Spells of Level 1+:** You prepare the list of level 1+ spells that are available for you to cast with this feature. Choose four level 1 spells from the Cleric spell list to start. The number of spells on your list increases as you gain Cleric levels. The chosen spells must be of a level for which you have spell slots.","**Changing Your Prepared Spells:** Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with other Cleric spells for which you have spell slots.","**Spellcasting Ability:** Wisdom is your spellcasting ability for your Cleric spells.","**Spellcasting Focus:** You can use a Holy Symbol as a Spellcasting Focus for your Cleric spells."],"name":"Spellcasting","index":"spellcasting-cleric","level":1,"source":"Cleric","effects":[]},{"url":"","desc":["You have dedicated yourself to one of the following sacred roles of your choice:","**Protector:** Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor. This is ideal for clerics who want to be in the thick of melee combat.","**Thaumaturge:** You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1). This is perfect for clerics focused on divine lore and magic."],"name":"Divine Order","index":"divine-order","level":1,"source":"Cleric","effects":[{"name":"Divine Order","type":"feature_choice","count":1,"options":[{"desc":"Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor. This is ideal for clerics who want to be in the thick of melee combat.","name":"Protector","effects":[{"type":"proficiency","target":"martial-weapons","category":"weapon"},{"type":"proficiency","target":"heavy-armor","category":"armor"}]},{"desc":"You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1). This is perfect for clerics focused on divine lore and magic.","name":"Thaumaturge","effects":[{"type":"spell_access","count":1,"level":0,"filter_class":"Cleric"},{"stat":"arcana_bonus","type":"stat_bonus_attribute","attribute":"wis"},{"stat":"religion_bonus","type":"stat_bonus_attribute","attribute":"wis"}]}]}]},{"url":"","desc":["You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead.","You can use this class’s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses at higher levels.","**Divine Spark:** As a Magic action, point your Holy Symbol at a creature within 30 feet. Roll 1d8 + Wisdom modifier. You either restore HP to the creature equal to that total or force it to make a Constitution save. On a failed save, it takes Necrotic or Radiant damage (your choice) equal to the total. On a success, it takes half as much damage. The d8s increase at levels 7 (2d8), 13 (3d8), and 18 (4d8).","**Turn Undead:** As a Magic action, present your Holy Symbol. Each Undead of your choice within 30 feet must make a Wisdom save. On a failure, it is Frightened and Incapacitated for 1 minute or until it takes damage."],"name":"Channel Divinity","index":"channel-divinity","level":2,"source":"Cleric","effects":[{"name":"Channel Divinity","type":"action","description":"Channel divine energy to produce a magical effect."}]},{"url":"","desc":["You gain a Cleric subclass of your choice at level 3."],"name":"Divine Domain","index":"cleric-subclass","level":3,"source":"Cleric","effects":[]},{"url":"","desc":["Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8). Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll’s total. This damage doesn’t end the turn effect."],"name":"Sear Undead","index":"sear-undead","level":5,"source":"Cleric","effects":[{"name":"Sear Undead","type":"action","description":"Turn or damage undead with Channel Divinity."}]},{"url":"","desc":["Divine power infuses you in battle. Choose one of the following options:","**Divine Strike:** Once on each of your turns when you hit a creature with an attack roll using a weapon, you can cause the target to take an extra 1d8 Necrotic or Radiant damage (your choice).","**Potent Spellcasting:** Add your Wisdom modifier to the damage you deal with any Cleric cantrip."],"name":"Blessed Strikes","index":"blessed-strikes","level":7,"source":"Cleric","effects":[{"name":"Blessed Strikes","type":"feature_choice","count":1,"options":[{"desc":"Extra 1d8 Necrotic or Radiant damage once per turn on weapon hit.","name":"Divine Strike","effects":[{"desc":"Extra 1d8 damage on weapon attacks once per turn.","name":"Divine Strike","type":"feature"}]},{"desc":"Add Wis modifier to Cleric cantrip damage.","name":"Potent Spellcasting","effects":[{"desc":"Add Wis modifier to Cleric cantrip damage.","name":"Potent Spellcasting","type":"feature"}]}]}]},{"url":"","desc":["You can call on your deity to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn’t require a Reaction to cast. You cast that spell without expending a spell slot or needing Material components. You can’t use this feature again until you finish a Long Rest."],"name":"Divine Intervention","index":"divine-intervention","level":10,"source":"Cleric","effects":[{"name":"Divine Intervention","type":"action","description":"Call on your deity for aid."}]},{"url":"","desc":["The option you chose for Blessed Strikes grows more powerful.","**Divine Strike:** The extra damage increases to 2d8.","**Potent Spellcasting:** When you cast a Cleric cantrip and deal damage, you can grant temporary HP equal to twice your Wisdom modifier to yourself or another creature within 60 feet."],"name":"Improved Blessed Strikes","index":"improved-blessed-strikes","level":14,"source":"Cleric","effects":[]},{"url":"","desc":["You gain an Epic Boon feat or another feat of your choice for which you qualify."],"name":"Epic Boon","index":"epic-boon-cleric","level":19,"source":"Cleric","effects":[]},{"url":"","desc":["When you use your Divine Intervention feature, you can choose Wish when you select a spell. If you do so, you can’t use Divine Intervention again until you finish 2d4 Long Rests."],"name":"Greater Divine Intervention","index":"greater-divine-intervention","level":20,"source":"Cleric","effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: History","index":"history"}},{"item":{"url":"","name":"Skill: Insight","index":"insight"}},{"item":{"url":"","name":"Skill: Medicine","index":"medicine"}},{"item":{"url":"","name":"Skill: Persuasion","index":"persuasion"}},{"item":{"url":"","name":"Skill: Religion","index":"religion"}}]},"type":"proficiencies","choose":2}]}$persona_content_migration$::jsonb,
