bclass_label":"Bard College","subclass_level":3,"feature_details":[{"url":"","desc":["You can inspire others through stirring words or music. Use a Bonus Action to grant a Bardic Inspiration die to a creature within 60 feet. The die is a d6 (increasing at later levels). The creature can add the die to one ability check, attack roll, or saving throw it makes within 10 minutes. You can use this feature a number of times equal to your Charisma modifier, regaining all uses on a Long Rest (Short Rest at level 5)."],"name":"Bardic Inspiration","index":"bardic-inspiration","level":1,"source":"Bard","effects":[{"name":"Bardic Inspiration","type":"bonus_action","description":"Give a creature a Bardic Inspiration die."}]},{"url":"","desc":["You have learned to untangle and reshape the fabric of reality in harmony with your music and performance."],"name":"Spellcasting","index":"spellcasting-bard","level":1,"source":"Bard","effects":[]},{"url":"","desc":["Choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies."],"name":"Expertise","index":"expertise-bard","level":2,"source":"Bard","effects":[{"type":"expertise_choice","count":2,"category":"skill"}]},{"url":"","desc":["You can add half your proficiency bonus, rounded down, to any ability check you make that doesn't already include your proficiency bonus."],"name":"Jack of All Trades","index":"jack of all trades","level":2,"source":"Bard","effects":[{"name":"Jack of All Trades","type":"half_proficiency","target":"ability_checks"}]},{"url":"","desc":["You delve into the advanced techniques of a bard college of your choice."],"name":"Bard Subclass","index":"bard-subclass","level":3,"source":"Bard","effects":[]},{"url":"","desc":["You regain all of your expended uses of Bardic Inspiration when you finish a Short or Long Rest."],"name":"Font of Inspiration","index":"font-of-inspiration","level":5,"source":"Bard","effects":[{"name":"Font of Inspiration","type":"feature","description":"Regain Bardic Inspiration uses on a short rest."}]},{"url":"","desc":["As a Reaction when you or an ally within 30 feet fails a save against being Charmed or Frightened, you can grant a reroll with Advantage."],"name":"Countercharm","index":"countercharm","level":7,"source":"Bard","effects":[{"name":"Countercharm","type":"action","description":"Grant advantage against being frightened or charmed."}]},{"url":"","desc":["Choose two more of your skill proficiencies. Your proficiency bonus is doubled for these choices."],"name":"Expertise","index":"expertise-bard-9","level":9,"source":"Bard","effects":[{"type":"expertise_choice","count":2,"category":"skill"}]},{"url":"","desc":["Your mastery of the weave allows you to learn spells from any class list. Whenever you gain a Bard level or finish a Long Rest, you can replace one of your Bard spells with a spell from the Cleric, Druid, or Wizard spell list."],"name":"Magical Secrets","index":"magical-secrets","level":10,"source":"Bard","effects":[{"name":"Magical Secrets","type":"feature","description":"Learn spells from any class list."}]},{"url":"","desc":["When you roll initiative and have no uses of Bardic Inspiration remaining, you regain two uses."],"name":"Superior Inspiration","index":"superior-inspiration","level":18,"source":"Bard","effects":[]},{"url":"","desc":["You gain an Epic Boon feat of your choice."],"name":"Epic Boon","index":"epic-boon-bard","level":19,"source":"Bard","effects":[]},{"url":"","desc":["You have mastered the most powerful musical utterances. You always have Power Word Heal and Power Word Kill prepared, and when you cast either, you can target a second creature within 10 feet of the first."],"name":"Words of Creation","index":"words-of-creation","level":20,"source":"Bard","effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Acrobatics","index":"acrobatics"}},{"item":{"url":"","name":"Skill: Animal Handling","in