ic":{"focus_points":4,"martial_arts":"1d6","unarmored_movement":10}},{"level":5,"features":["Extra Attack","Stunning Strike"],"prof_bonus":3,"class_specific":{"focus_points":5,"martial_arts":"1d8","unarmored_movement":10}},{"level":6,"features":["Empowered Strikes","Subclass feature"],"prof_bonus":3,"class_specific":{"focus_points":6,"martial_arts":"1d8","unarmored_movement":15}},{"level":7,"features":["Evasion"],"prof_bonus":3,"class_specific":{"focus_points":7,"martial_arts":"1d8","unarmored_movement":15}},{"level":8,"features":["Ability Score Improvement"],"prof_bonus":3,"class_specific":{"focus_points":8,"martial_arts":"1d8","unarmored_movement":15}},{"level":9,"features":["Acrobatic Movement"],"prof_bonus":4,"class_specific":{"focus_points":9,"martial_arts":"1d8","unarmored_movement":15}},{"level":10,"features":["Heightened Focus","Self-Restoration"],"prof_bonus":4,"class_specific":{"focus_points":10,"martial_arts":"1d8","unarmored_movement":20}},{"level":11,"features":["Subclass feature"],"prof_bonus":4,"class_specific":{"focus_points":11,"martial_arts":"1d10","unarmored_movement":20}},{"level":12,"features":["Ability Score Improvement"],"prof_bonus":4,"class_specific":{"focus_points":12,"martial_arts":"1d10","unarmored_movement":20}},{"level":13,"features":["Deflect Energy"],"prof_bonus":5,"class_specific":{"focus_points":13,"martial_arts":"1d10","unarmored_movement":20}},{"level":14,"features":["Disciplined Survivor"],"prof_bonus":5,"class_specific":{"focus_points":14,"martial_arts":"1d10","unarmored_movement":25}},{"level":15,"features":["Perfect Focus"],"prof_bonus":5,"class_specific":{"focus_points":15,"martial_arts":"1d10","unarmored_movement":25}},{"level":16,"features":["Ability Score Improvement"],"prof_bonus":5,"class_specific":{"focus_points":16,"martial_arts":"1d10","unarmored_movement":25}},{"level":17,"features":["Subclass feature"],"prof_bonus":6,"class_specific":{"focus_points":17,"martial_arts":"1d12","unarmored_movement":25}},{"level":18,"features":["Superior Defense"],"prof_bonus":6,"class_specific":{"focus_points":18,"martial_arts":"1d12","unarmored_movement":30}},{"level":19,"features":["Epic Boon"],"prof_bonus":6,"class_specific":{"focus_points":19,"martial_arts":"1d12","unarmored_movement":30}},{"level":20,"features":["Body and Mind"],"prof_bonus":6,"class_specific":{"focus_points":20,"martial_arts":"1d12","unarmored_movement":30}}],"proficiencies":[{"url":"","name":"Simple Weapons","index":"simple-weapons"},{"url":"","name":"Martial Weapons with the Light property","index":"martial-weapons-light"}],"saving_throws":[{"url":"","name":"STR","index":"str"},{"url":"","name":"DEX","index":"dex"}],"schema_version":2,"subclass_label":"Monastic Tradition","subclass_level":3,"feature_details":[{"url":"","desc":["Your practice of martial arts gives you mastery of combat styles that use unarmed strikes and Monk weapons (Simple weapons and Martial weapons with the Light property).","**Dexterous Attacks:** You can use Dexterity instead of Strength for the attack and damage rolls of your unarmed strikes and Monk weapons.","**Martial Arts Die:** You can roll your Martial Arts die (starting at 1d6) in place of the normal damage of your unarmed strike or Monk weapon. This die increases as you reach higher Monk levels.","**Bonus Unarmed Strike:** When you take the Attack action with an unarmed strike or a Monk weapon on your turn, you can make one unarmed strike as a bonus action on the same turn."],"name":"Martial Arts","index":"martial-arts-2024","level":1,"source":"Monk","effects":[{"name":"Martial Arts Strike","type":"bonus_action","description":"When you take the Attack action with an unarmed strike or a Monk weapon on your turn, you can make one unarmed strike as a bonus action on the same turn."}]},{"url":"","desc":["While you are wearing no armor and not wielding a shield, your Armor Class equals 10 + your Dexterity modifier + your Wisdom modifier."],"name":"Unarmored Defense","index":"unarmored-defense-monk","level":1,"source":"Monk","effects":[{"stat":"ac","type":"stat_bonus_attribute","attribute":"wis"},{"name":"Unarmored Defense","stat":"ac","type":"stat_bonus_attribute","attribute":"wis"}]},{"url":"","desc":["You can channel your inner focus to perform supernatural feats. You have a number of Focus Points equal to your Monk level.","**Flurry of Blows:** Immediately after you take the Attack action on your turn, you can spend 1 Focus Point to make two unarmed strikes as a bonus action.","**Patient Defense:** You can take the Disengage action as a bonus action. Alternatively, you can spend 1 Focus Point to take the Dodge action as a bonus action.","**Step of the Wind:** You can take the Dash action as a bonus action. Alternatively, you can spend 1 Focus Point to take the Disengage action as a bonus action, and your jump distance is doubled for the turn.","You regain all expended Focus Points when you finish a Short or Long Rest."],"name":"Monk's Focus","index":"monks-focus","level":2,"source":"Monk","effects":[{"name":"Flurry of Blows","type":"bonus_action","description":"Immediately after you take the Attack action on your turn, you can spend 1 Focus Point to make two unarmed strikes as a bonus action."},{"name":"Patient Defense","type":"bonus_action","description":"You can take the Disengage action as a bonus action. Alternatively, you can spend 1 Focus Point to take the Dodge action as a bonus action."},{"name":"Step of the Wind","type":"bonus_action","description":"You can take the Dash action as a bonus action. Alternatively, you can spend 1 Focus Point to take the Disengage action as a bonus action, and your jump distance is doubled for the turn."}]},{"url":"","desc":["Your speed increases by the amount shown in the Monk table while you are not wearing armor or wielding a shield."],"name":"Unarmored Movement","index":"unarmored-movement-monk","level":2,"source":"Monk","effects":[{"name":"Unarmored Movement","stat":"speed","type":"stat_bonus","value":{"type":"table","values":[0,10,10,10,10,15,15,15,15,20,20,20,20,25,25,25,25,30,30,30]},"condition":"no_armor_no_shield"}]},{"url":"","desc":["When you roll Initiative, you can regain all expended Focus Points. When you do so, you also regain HP equal to your Monk level + Wisdom modifier. Once you use this feature, you can't do so again until you finish a Long Rest."],"name":"Uncanny Metabolism","index":"uncanny-metabolism","level":2,"source":"Monk","effects":[{"name":"Uncanny Metabolism","type":"feature","description":"When you roll Initiative, you can regain all expended Focus Points. When you do so, you also regain HP equal to your Monk level + Wisdom modifier. Once you use this feature, you can't do so again until you finish a Long Rest."}]},{"url":"","desc":["You can use your reaction to deflect or catch the missile when you are hit by a ranged weapon attack or reduce damage from a melee attack.","**Damage Reduction:** When you are hit by an attack, you can reduce the damage by 1d10 + your Dexterity modifier + your Monk level.","**Redirect Attack:** If you reduce the damage to 0, you can spend 1 Focus Point to redirect the attack. If it was a ranged attack, you catch the missile and can make a ranged attack with it (range 20/60). If it was a melee attack, you can make an unarmed strike against a creature within 5 feet of you as part of the same reaction."],"name":"Deflect Attacks","index":"deflect-attacks","level":3,"source":"Monk","effects":[{"name":"Deflect Attacks","type":"reaction","description":"Reduce damage from an attack; can redirect if damage is 0."}]},{"url":"","desc":["You can use your reaction when you fall to reduce any falling damage you take by an amount equal to five times your Monk level."],"name":"Slow Fall","index":"slow-fall","level":4,"source":"Monk","effects":[{"name":"Slow Fall","type":"reaction","description":"Reduce falling damage by 5x Monk level."}]},{"url":"","desc":["You can attack twice, instead of once, whenever you take the Attack action on your turn."],"name":"Extra Attack","index":"extra-attack-monk","level":5,"source":"Monk","effects":[{"mode":"set","name":"Extra Attack","type":"extra_attack","value":2}]},{"url":"","desc":["Once per turn when you hit a creature with a Monk weapon or an unarmed strike, you can spend 1 Focus Point to attempt a Stunning Strike.","The target must succeed on a Constitution saving throw or be Stunned until the end of your next turn. If the target succeeds on the save, its speed is halved until the start of your next turn."],"name":"Stunning Strike","index":"stunning-strike","level":5,"source":"Monk","effects":[{"name":"Stunning Strike","type":"feature","description":"Spend 1 Focus Point to stun or slow a target on hit."}]},{"url":"","desc":["Whenever you deal damage with your Unarmed Strike, it can deal Force damage or its normal damage type."],"name":"Empowered Strikes","index":"empowered-strikes","level":6,"source":"Monk","effects":[{"name":"Empowered Strikes","type":"feature","description":"Unarmed strikes can deal Force damage or their normal damage type."},{"name":"Empowered Strikes","type":"attack_rider","condition":"unarmed","description":"Whenever you deal damage with your Unarmed Strike, it can deal Force damage or its normal damage type."}]},{"url":"","desc":["When you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail."],"name":"Evasion","index":"evasion-monk","level":7,"source":"Monk","effects":[{"name":"Evasion","type":"feature","description":"Take no damage on successful Dex save, half on fail."}]},{"url":"","desc":["While you aren't wearing armor or wielding a shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the move."],"name":"Acrobatic Movement","index":"acrobatic-movement","level":9,"source":"Monk","effects":[]},{"url":"","desc":["Your Monk's Focus features are improved:","**Flurry of Blows:** You can make three unarmed strikes instead of two when you use Flurry of Blows.","**Patient Defense:** When you use Patient Defense, you gain Temporary HP equal to two rolls of your Martial Arts die.","**Step of the Wind:** When you use Step of the Wind, your jump distance is doubled for the turn, and you can move a creature that is your size or smaller with you when you move. This movement doesn't provoke opportunity attacks for either of you."],"name":"Heightened Focus","index":"heightened-focus","level":10,"source":"Monk","effects":[{"name":"Heightened Flurry","type":"feature","description":"Flurry of Blows now makes 3 attacks."},{"name":"Heightened Patient Defense","type":"feature","description":"Patient Defense grants Temp HP."},{"name":"Heightened Step of the Wind","type":"feature","description":"Step of the Wind allows moving others and doubles jump."}]},{"url":"","desc":["Through sheer force of will, you can remove one of the following conditions from yourself at the end of your turn: Charmed, Frightened, or Poisoned.","In addition, forgoing food and drink doesn't give you levels of exhaustion."],"name":"Self-Restoration","index":"self-restoration","level":10,"source":"Monk","effects":[{"name":"Self-Restoration","type":"feature","description":"Remove Charmed/Frightened/Poisoned at end of turn."}]},{"url":"","desc":["You can use your Deflect Attacks feature against attacks that deal any damage type, not just bludgeoning, piercing, or slashing."],"name":"Deflect Energy","index":"deflect-energy","level":13,"source":"Monk","effects":[]},{"url":"","desc":["Your physical and mental discipline grant you proficiency in all saving throws.","Additionally, whenever you make a saving throw and fail, you can spend 1 Focus Point to reroll it and take the second result."],"name":"Disciplined Survivor","index":"disciplined-survivor","level":14,"source":"Monk","effects":[{"type":"proficiency","target":"STR","category":"save"},{"type":"proficiency","target":"DEX","category":"save"},{"type":"proficiency","target":"CON","category":"save"},{"type":"proficiency","target":"INT","category":"save"},{"type":"proficiency","target":"WIS","category":"save"},{"type":"proficiency","target":"CHA","category":"save"}]},{"url":"","desc":["When you roll Initiative and have 0 Focus Points remaining, you regain 4 Focus Points."],"name":"Perfect Focus","index":"perfect-focus","level":15,"source":"Monk","effects":[]},{"url":"","desc":["As a Bonus Action, you can spend 3 Focus Points to gain resistance to all damage except Force damage for 1 minute or until you are incapacitated."],"name":"Superior Defense","index":"superior-defense","level":18,"source":"Monk","effects":[{"name":"Superior Defense","type":"bonus_action","description":"As a Bonus Action, you can spend 3 Focus Points to gain resistance to all damage except Force damage for 1 minute or until you are incapacitated."}]},{"url":"","desc":["Your Dexterity and Wisdom scores increase by 4. Your maximum for those scores is now 24."],"name":"Body and Mind","index":"body-and-mind","level":20,"source":"Monk","effects":[{"type":"bonus","value":4,"target":"dex"},{"type":"bonus","value":4,"target":"wis"}]}],"primary_ability":["dex","wis"],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Acrobatics","index":"acrobatics"}},{"item":{"url":"","name":"Skill: Athletics","index":"athletics"}},{"item":{"url":"","name":"Skill: History","index":"history"}},{"item":{"url":"","name":"Skill: Insight","index":"insight"}},{"item":{"url":"","name":"Skill: Religion","index":"religion"}},{"item":{"url":"","name":"Skill: Stealth","index":"stealth"}}]},"type":"proficiencies","choose":2},{"from":{"options":[{"url":"","name":"Artisan's Tools","index":"artisan-tools"},{"url":"","name":"Musical Instrument","index":"musical-instruments"}]},"type":"proficiencies","choose":1}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'monk'),
       source = 'Player''s Handbook 2024',
       migrated_at = now()
 where id = 'c72c8959-7724-4e16-968e-f2fda93b57ae';

-- Arrowsmith (arrowsmith)
update public.custom_classes
   set data = $persona_content_migration${"id":"e433afe3-c675-4741-9dfe-003c4bb16ed1","ui":{},"desc":[""],"name":"Arrowsmith","index":"arrowsmith","rules":[{"desc":"If within 15 ft of 2+ enemies, AC increases by +2, and +1 for every additional 2 enemies.","name":"Into The Frey","category":"Custom"},{"desc":"When reloading, you can move 5 ft without provoking opportunity attacks.","name":"Rolling Reload","category":"Custom"}],"caster":{"type":"none"},"source":"Homebrew","choices":[{"id":"arrowsmith-proficiency-0","kind":"proficiency","count":3,"source":"class","options":[{"name":"Arcana","index":"arcana","category":"skill","rawName":"Skill: Arcana"},{"name":"Athletics","index":"athletics","category":"skill","rawName":"Skill: Athletics"},{"name":"Insight","index":"insight","category":"skill","rawName":"Skill: Insight"},{"name":"Investigation","index":"investigation","category":"skill","rawName":"Skill: Investigation"},{"name":"Nature","index":"nature","category":"skill","rawName":"Skill: Nature"},{"name":"Perception","index":"perception","category":"skill","rawName":"Skill: Perception"},{"name":"Stealth","index":"stealth","category":"skill","rawName":"Skill: Stealth"},{"name":"Sleight of Hand","index":"sleight-of-hand","category":"skill","rawName":"Skill: Sleight of Hand"},{"name":"Survival","index":"survival","category":"skill","rawName":"Skill: Survival"}]}],"hit_die":10,"options":{"arrows":[{"name":"Silent","level":1,"desc":"Hidden hits don't reveal position. Crits on surprised.","notes":["Crit Surprised"]},{"name":"Forceful","level":1,"desc":"On hit, STR Save DC {dc} or pushed 20ft.","saveType":"STR"},{"name":"Fire","level":1,"desc":"Extra 1d10 fire. Ignites for 1d6/turn (DC 10 Dex).","dmgPlus":"+1d10","type":"Fire"},{"name":"Shattering","level":2,"desc":"10ft cone behind target. DEX Save {dc} half.","saveType":"DEX"},{"name":"Smokescreen","level":2,"desc":"Creates 20ft fog sphere centered on hit. 1 min.","type":"Other"},{"name":"Light","level":3,"desc":"Bonus action attack. Ignore reload.","type":"Piercing","notes":["Bonus Action","Ignore Reload"]},{"name":"Sniper","level":3,"desc":"Double normal and long range for this shot.","rangeLabel":"Double Range"},{"name":"Piercing","level":4,"desc":"Pierce 20ft line. Ignore resistance.","notes":["Ignore Resist"]},{"name":"Blinding","level":4,"desc":"Explodes after 10-30ft. CON Save {dc} or Blinded.","saveType":"CON"},{"name":"Explosive","level":5,"desc":"5d6 Force AoE (Dex Save {dc} half).","dmg":"5d6","addBaseDamage":true,"type":"Force","saveType":"DEX"},{"name":"Knockdown","level":5,"desc":"On hit, STR Save {dc} or knocked prone.","saveType":"STR"},{"name":"Elemental","spec":"magic-as","desc":"+2d6 Cold/Fire/Lit/Necro/Rad.","dmgPlus":"+2d6","level":5},{"name":"Spectral","spec":"magic-as","desc":"Traverses matter. Ignore all cover.","notes":["Ignore Cover"],"level":6},{"name":"Cursed","spec":"magic-as","desc":"+1d8 Necrotic. No healing for target.","dmgPlus":"+1d8","type":"Necrotic","level":7},{"name":"Seeking","spec":"magic-as","desc":"Auto-hit any opponent you see.","autoHit":true,"notes":["Auto-Hit"],"level":8},{"name":"Shifter","spec":"magic-as","desc":"Teleport to arrow location (Max 50ft).","level":9},{"name":"Intoxicating","spec":"toxins-as","desc":"Disadv on attacks until end of next turn.","notes":["Debuff"],"level":5},{"name":"Paralytic","spec":"toxins-as","desc":"CON Save DC {dc} or Paralyzed.","saveType":"CON","level":6},{"name":"Toxic Cloud","spec":"toxins-as","desc":"15ft cloud. CON Save or 1d10 Poison + Stunned.","saveType":"CON","level":7},{"name":"Furious","spec":"toxins-as","desc":"WIS Save DC {dc} or attack closest.","saveType":"WIS","level":8},{"name":"Sleeping","spec":"toxins-as","desc":"1d6s vs HP. Success = Sleep.","level":9},{"name":"Healing","spec":"support-as","desc":"Heals target for half damage rolled.","calc":"halfBow","type":"Healing","level":5},{"name":"Vigorous","spec":"support-as","desc":"Grant Int+Prof Temp HP and +2 AC.","type":"Buff","level":6},{"name":"Anti-Healing","spec":"support-as","desc":"Target cannot regain health for 1 min.","level":7},{"name":"Adrenaline","spec":"support-as","desc":"+15ft move and Adv on attacks/saves.","type":"Buff","level":8},{"name":"Affection","spec":"support-as","desc":"WIS Save DC {dc} or Charmed.","saveType":"WIS","level":9}],"arrowCrafting":true},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"resources":[{"key":"arrow-crafting","max":{"type":"table","values":[2,3,4,5,6,7,8,9,10,10,11,11,12,12,13,13,14,14,15,15]},"name":"Arrow Crafting","level":1,"reset":"short","source":"Arrowsmith"}],"spell_list":[],"is_homebrew":true,"level_table":[{"level":1,"features":["Arrowsmith"],"prof_bonus":2},{"level":2,"features":["Fighting Style"],"prof_bonus":2},{"level":3,"features":["Rolling Reload"],"prof_bonus":2},{"level":4,"features":[],"prof_bonus":2},{"level":5,"features":["Extra Attack"],"prof_bonus":3},{"level":6,"features":["Into The Frey"],"prof_bonus":3},{"level":7,"features":["Craftsman"],"prof_bonus":3},{"level":8,"features":[],"prof_bonus":3},{"level":9,"features":["Camouflage Crafter"],"prof_bonus":4},{"level":10,"features":["Made to Kill (1)"],"prof_bonus":4},{"level":11,"features":[],"prof_bonus":4},{"level":12,"features":[],"prof_bonus":4},{"level":13,"features":[],"prof_bonus":5},{"level":14,"features":[],"prof_bonus":5},{"level":15,"features":["Shared Knowledge"],"prof_bonus":5},{"level":16,"features":[],"prof_bonus":5},{"level":17,"features":["Trained Archer"],"prof_bonus":6},{"level":18,"features":["Combined Custom Arrows"],"prof_bonus":6},{"level":19,"features":[],"prof_bonus":6},{"level":20,"features":["Advanced Combined Custom Arrows"],"prof_bonus":6}],"proficiencies":[{"name":"Light Armor"},{"name":"Medium Armor"},{"name":"Simple Weapons"},{"name":"Martial Weapons"},{"name":"Tinker's Tools"}],"saving_throws":[{"name":"DEX","index":"dex"},{"name":"WIS","index":"wis"}],"schema_version":2,"subclass_label":"Specialization","subclass_level":3,"feature_details":[{"desc":["You craft specialized arrows using Tinker's Tools. You can craft a number of arrows per short/long rest, up to your carrying capacity. Saving throw DC = 8 + Proficiency + Intelligence modifier."],"name":"Arrowsmith","index":"arrowsmith","level":1,"effects":[]},{"desc":["Adopt a particular style of fighting as your specialty."],"name":"Fighting Style","index":"fighting-style","level":2,"effects":[{"name":"Fighting Style","type":"feature_choice","count":1,"options":[{"desc":"You gain a +2 bonus to Attack Rolls you make with Ranged Weapons.","name":"Archery","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":2}]},{"desc":"While you are wearing armor, you gain a +1 bonus to AC.","name":"Defense","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.","name":"Dueling","effects":[{"stat":"weapon_damage","type":"stat_bonus","value":2}]},{"desc":"When you roll a 1 or 2 on a damage die for an attack you make with a melee weapon that you are wielding with two hands, you can reroll the die and must use the new roll.","name":"Great Weapon Fighting"},{"desc":"When a creature you can see attacks a target other than you that is within 5 feet of you, you can use your reaction to impose disadvantage on the attack roll. You must be wielding a shield.","name":"Protection"},{"desc":"When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.","name":"Two-Weapon Fighting"},{"desc":"As long as you are not wearing armor or using a shield, you have a swimming speed and a climbing speed equal to your normal speed, and you gain a +1 bonus to AC.","name":"Mariner","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"You are trained in making ranged attacks at close quarters. When making a ranged attack while you are within 5 feet of a hostile creature, you do not have disadvantage on the attack roll. Your ranged attacks ignore half cover and three-quarter cover against targets within 30 feet of you. Finally, you have a +1 bonus to attack rolls on ranged attacks.","name":"Close Quarters Shooter","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":1}]},{"desc":"When a teammate misses an opportunity attack against an enemy you can see, you can use your reaction to make an opportunity attack against the same target, as long as they are in range.","name":"Opportune Ranger"}]}]},{"desc":["Whenever you reload a weapon, you can move 5 ft. This movement is treated as a disengage and does not provoke opportunity attacks."],"name":"Rolling Reload","index":"rolling-reload","level":3,"effects":[{"name":"Rolling Reload","type":"feature","description":"Reload while moving without provoking opportunity attacks."}]},{"desc":["You can attack twice whenever you take the Attack action."],"name":"Extra Attack","index":"extra-attack","level":5,"effects":[{"mode":"set","name":"Extra Attack","type":"extra_attack","value":2}]},{"desc":["Being within 15 ft of 2 enemies increases AC by +2. Add +1 for every additional 2 enemies."],"name":"Into The Frey","index":"into-the-frey","level":6,"effects":[{"name":"Into The Frey","type":"feature","description":"Gain AC when surrounded by enemies."}]},{"desc":["Gain proficiency in one artisan's tool of your choice."],"name":"Craftsman","index":"craftsman","level":7,"effects":[{"type":"proficiency_choice","count":1,"category":"tool"}]},{"desc":["Spend 1 minute to create wearable camouflage. Grants proficiency to Stealth checks and removes disadvantage from armor. Lasts 10 minutes or until you move."],"name":"Camouflage Crafter","index":"camouflage-crafter","level":9,"effects":[]},{"desc":["Your Custom Arrows gain a +1 bonus to attack and damage rolls."],"name":"Made to Kill (1)","index":"made-to-kill-(1)","level":10,"effects":[]},{"desc":["Choose additional special arrows from other specializations."],"name":"Shared Knowledge","index":"shared-knowledge","level":15,"effects":[]},{"desc":["When attacking with a custom arrow, add Intelligence modifier to attack and damage rolls. Uses: Int mod per Short Rest."],"name":"Trained Archer","index":"trained-archer","level":17,"effects":[]},{"desc":["Combine a base Custom Arrow with a Specialization arrow."],"name":"Combined Custom Arrows","index":"combined-custom-arrows","level":18,"effects":[]},{"desc":["Combine 2 base Custom Arrows with a Specialization arrow. Costs 2 craft points."],"name":"Advanced Combined Custom Arrows","index":"advanced-combined-custom-arrows","level":20,"effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Arcana","index":"arcana"}},{"item":{"url":"","name":"Skill: Athletics","index":"athletics"}},{"item":{"url":"","name":"Skill: Insight","index":"insight"}},{"item":{"url":"","name":"Skill: Investigation","index":"investigation"}},{"item":{"url":"","name":"Skill: Nature","index":"nature"}},{"item":{"url":"","name":"Skill: Perception","index":"perception"}},{"item":{"url":"","name":"Skill: Stealth","index":"stealth"}},{"item":{"url":"","name":"Skill: Sleight of Hand","index":"sleight-of-hand"}},{"item":{"url":"","name":"Skill: Survival","index":"survival"}}]},"type":"proficiencies","choose":3}]}$persona_content_migration$::jsonb,
