       slug = coalesce(slug, 'arrowsmith'),
       source = 'Homebrew',
       migrated_at = now()
 where id = 'e433afe3-c675-4741-9dfe-003c4bb16ed1';

-- Warlock (warlock)
update public.custom_classes
   set data = $persona_content_migration${"ui":{},"name":"Warlock","index":"warlock","rules":[],"caster":{"type":"pact","ability":"cha"},"source":"Player's Handbook 2024","choices":[{"id":"warlock-proficiency-0","kind":"proficiency","count":2,"source":"class","options":[{"name":"Arcana","index":"arcana","category":"skill","rawName":"Skill: Arcana"},{"name":"Deception","index":"deception","category":"skill","rawName":"Skill: Deception"},{"name":"History","index":"history","category":"skill","rawName":"Skill: History"},{"name":"Intimidation","index":"intimidation","category":"skill","rawName":"Skill: Intimidation"},{"name":"Investigation","index":"investigation","category":"skill","rawName":"Skill: Investigation"},{"name":"Nature","index":"nature","category":"skill","rawName":"Skill: Nature"},{"name":"Religion","index":"religion","category":"skill","rawName":"Skill: Religion"}]}],"hit_die":8,"options":{"invocations":[{"name":"Agonizing Blast","desc":"Add your Charisma modifier to Eldritch Blast damage.","effects":[{"type":"attack_rider","name":"Agonizing Blast","condition":"spell:eldritch blast","description":"Add your Charisma modifier to the damage Eldritch Blast deals on a hit."},{"type":"spell_damage_bonus","name":"Agonizing Blast","ability":"cha","spell":"Eldritch Blast"}]},{"name":"Armor of Shadows","desc":"Cast Mage Armor on yourself at will.","effects":[{"type":"set","stat":"ac","target":"ac","value":13,"condition":"no_armor"}]},{"name":"Devil's Sight","desc":"See normally in darkness, both magical and nonmagical, to 120 feet.","effects":[{"type":"set","target":"darkvision","value":120}]},{"name":"Eldritch Mind","desc":"Advantage on Constitution saving throws to maintain concentration.","effects":[{"type":"advantage","target":"saves","filter":"Concentration"}]},{"name":"Eldritch Spear","desc":"Eldritch Blast range becomes 300 feet."},{"name":"Fiendish Vigor","desc":"Cast False Life on yourself at will.","effects":[{"type":"feature","name":"Fiendish Vigor","des