"Light Armor","index":"light-armor"},{"url":"","name":"Simple Weapons","index":"simple-weapons"}],"saving_throws":[{"url":"","name":"WIS","index":"wis"},{"url":"","name":"CHA","index":"cha"}],"schema_version":2,"subclass_label":"Otherworldly Patron","subclass_level":3,"feature_details":[{"url":"","desc":["In your study of occult lore, you have unearthed eldritch invocations, fragments of forbidden knowledge that imbue you with an abiding magical ability. You gain additional invocations as you level up."],"name":"Eldritch Invocations","index":"eldritch-invocations-2024","level":1,"source":"Warlock","effects":[{"name":"Eldritch Invocations","type":"feature","description":"Learn fragments of forbidden knowledge."}]},{"url":"","desc":["Your arcane research and the magic bestowed on you by your patron have given you facility with spells. You use Charisma as your spellcasting ability. Your warlock spell slots are all of the same level and you regain all expended Pact Magic slots when you finish a Short or Long Rest."],"name":"Pact Magic","index":"pact-magic-2024","level":1,"source":"Warlock","effects":[{"name":"Pact Magic","type":"feature","description":"Your spell slots recharge on a short rest."}]},{"url":"","desc":["Once per Long Rest, you can spend 1 minute to perform a ritual to regain half of your expended Pact Magic slots (rounded up)."],"name":"Magical Cunning","index":"magical-cunning","level":2,"source":"Warlock","effects":[{"name":"Magical Cunning","type":"feature","description":"Regain expended Pact Magic slots."}]},{"url":"","desc":["You can cast the Contact Other Plane spell without expending a spell slot once per Long Rest. You automatically succeed on the saving throw for this casting, and you contact your patron."],"name":"Contact Patron","index":"contact-patron","level":9,"source":"Warlock","effects":[]},{"url":"","desc":["Your patron bestows upon you a magical secret called an arcanum. Choose one 6th-level spell from the warlock spell list as this arcanum. You can cast your arcanum spell once without expending a spell slot. You must finish a Long Rest before you can do so again. You gain more arcana at levels 13, 15, and 17."],"name":"Mystic Arcanum","index":"mystic-arcanum","level":11,"source":"Warlock","effects":[{"name":"Mystic Arcanum","type":"feature","description":"Cast a high-level spell once per long rest without a slot."}]},{"url":"","desc":["You can draw on your inner reserve of mystical power to entreat your patron to regain all your expended Pact Magic slots. You can use this feature once per Long Rest."],"name":"Eldritch Master","index":"eldritch-master","level":20,"source":"Warlock","effects":[]}],"proficiency_choices":[{"from":{"options":[{"item":{"url":"","name":"Skill: Arcana","index":"arcana"}},{"item":{"url":"","name":"Skill: Deception","index":"deception"}},{"item":{"url":"","name":"Skill: History","index":"history"}},{"item":{"url":"","name":"Skill: Intimidation","index":"intimidation"}},{"item":{"url":"","name":"Skill: Investigation","index":"investigation"}},{"item":{"url":"","name":"Skill: Nature","index":"nature"}},{"item":{"url":"","name":"Skill: Religion","index":"religion"}}]},"type":"proficiencies","choose":2}]}$persona_content_migration$::jsonb,
