   set data = $persona_content_migration${"ui":{},"desc":["Focuses on Custom Arrows that can be helpful to their target."],"name":"Support Specialization","class":{"url":"","name":"Arrowsmith","index":"arrowsmith"},"index":"support-as","source":"Arrowsmith Specialization","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Specialization","subclass_level":3,"feature_details":[{"url":"","desc":["Gain proficiency in healing tools. You gain access to the Support Arrows table: Healing Arrow, Vigorous Arrow, Anti-Healing Arrow, Adrenaline Arrow, and Affection Arrow. Effects are doubled on a crit."],"name":"Support Arrowsmith","index":"support-as-prof","level":5,"source":"Support Specialization","effects":[{"type":"proficiency","target":"Healing tools","category":"tool"}]},{"url":"","desc":["At 8th level, you never miss a friendly creature with an arrow unless it is impossible to hit them."],"name":"Hold Still","index":"hold-still-as","level":8,"source":"Support Specialization","effects":[]},{"url":"","desc":["At 11th level, as a reaction, you can shoot a teammate who is being attacked by an enemy with a special arrow."],"name":"Medical Reaction","index":"medical-reaction-as","level":11,"source":"Support Specialization","effects":[]},{"url":"","desc":["At 14th level, when hitting yourself with one of your arrows, you always crit, doubling the effects."],"name":"Self Care","index":"self-care-as","level":14,"source":"Support Specialization","effects":[]}]}$persona_content_migration$::jsonb,
