-- Commander (commander)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["Commanders on the battlefield are a wonder to behold. Leading their troops to victory, they are tactical geniuses and experts at supporting their troops."],"name":"Commander","class":{"url":"","name":"Gunslinger","index":"gunslinger"},"index":"commander","source":"Gunslinger Bravado","resources":[{"key":"influence","max":{"type":"fixed","value":2},"name":"Influence","level":3,"reset":"long","source":"Commander"}],"spell_list":[],"schema_version":2,"subclass_label":"Gunslinger Archetype","subclass_level":3,"feature_details":[{"url":"","desc":["You learn the Moralize and Demoralize actions. Uses: 2 per Long Rest. Gained bonus/penalty increases at later levels."],"name":"Battlefield Influence","index":"battlefield-influence","level":3,"source":"Commander","effects":[{"name":"Battlefield Influence","type":"feature","description":"Spend Influence to direct allies."}]},{"url":"","desc":["While Moralize is active, you have advantage on all saving throws and ranged attack rolls made with a firearm."],"name":"Commanding Presence","index":"commanding-presence","level":7,"source":"Commander","effects":[]},{"url":"","desc":["Allies under Moralize can use a bonus action to deal extra 1d6 damage."],"name":"Stand as One","index":"stand-as-one","level":13,"source":"Commander","effects":[]},{"url":"","desc":["When you hit with a firearm, one ally gets advantage on their next attack."],"name":"Guiding Shot","index":"guiding-shot","level":15,"source":"Commander","effects":[]},{"url":"","desc":["You can train NPC soldiers (Scouts) equal to your Charisma modifier to serve as your loyal militia."],"name":"Militarized Mobilization","index":"militarized-mobilization","level":18,"source":"Commander","effects":[]}]}$persona_content_migration$::jsonb,
