   set data = $persona_content_migration${"ui":{},"desc":["Close Quarter Combatant experts prefer to be at the front line of combat, dealing damage and taking hits in place of other teammates."],"name":"CQC","class":{"url":"","name":"Gunslinger","index":"gunslinger"},"index":"cqc","source":"Gunslinger Bravado","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Gunslinger Archetype","subclass_level":3,"feature_details":[{"url":"","desc":["You gain +1 to AC while wearing armor (+2 at level 15)."],"name":"Armored Brute","index":"armored-brute","level":3,"source":"CQC","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"url":"","desc":["Firearms in melee don't have disadvantage. You can use Strength for firearm attack rolls."],"name":"CQC Training","index":"cqc-training","level":3,"source":"CQC","effects":[]},{"url":"","desc":["Your hit point maximum increases by an amount equal to twice your level."],"name":"Combat Conditioning","index":"combat-conditioning","level":7,"source":"CQC","effects":[{"stat":"hp_per_level","type":"stat_bonus","value":2}]},{"url":"","desc":["Bonus action to shove a creature 10 feet after a ranged firearm attack."],"name":"Crowd Control","index":"crowd-control","level":13,"source":"CQC","effects":[]},{"url":"","desc":["Proficiency with shields. Can mount a shield and still use two-handed firearms."],"name":"Riot Shield","index":"riot-shield","level":18,"source":"CQC","effects":[]}]}$persona_content_migration$::jsonb,
