-- Alchemist (alchemist)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["An Alchemist is an expert at combining exotic reagents to produce mystical effects. Among artificers, members of this subclass are the greatest healers, as well as the ones most adept at wielding dangerous chemicals."],"name":"Alchemist","class":{"url":"","name":"Artificer","index":"artificer"},"index":"alchemist","source":"Eberron","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Artificer Specialist","subclass_level":3,"feature_details":[{"url":"","desc":["You gain proficiency with alchemist's supplies. If you already have this proficiency, you gain proficiency with one other type of artisan's tools of your choice."],"name":"Tool Proficiency","index":"alchemist-tool-proficiency","level":3,"source":"Alchemist","effects":[{"type":"proficiency","target":"Alchemist's Supplies","category":"tool"}]},{"url":"","desc":["You always have certain spells prepared. 3rd: Purify Food and Drink, Ray of Sickness; 5th: Melf's Acid Arrow, Web; 9th: Create Food and Water, Stinking Cloud; 13th: Blight, Death Ward; 17th: Cloudkill, Raise Dead."],"name":"Alchemist Spells","index":"alchemist-spells","level":3,"source":"Alchemist","effects":[]},{"url":"","desc":["As an action, you can magically produce an experimental elixir in an empty flask you touch. Roll on the table for its effect. Creating an elixir requires alchemist's supplies."],"name":"Experimental Elixir","index":"experimental-elixir","level":3,"source":"Alchemist","effects":[]},{"url":"","desc":["Whenever you cast a spell using your alchemist's supplies as a spellcasting focus, you gain a bonus to one roll of the spell. The roll must restore HP or deal acid, fire, necrotic, or poison damage. The bonus equals your Intelligence modifier (min +1)."],"name":"Alchemical Savant","index":"alchemical-savant","level":5,"source":"Alchemist","effects":[]},{"url":"","desc":["Experimental elixirs now grant 2d6 + Int mod temporary HP. You can also cast Lesser Restoration without expending a spell slot (Int mod times per Long Rest)."],"name":"Restorative Reagents","index":"restorative-reagents","level":9,"source":"Alchemist","effects":[]},{"url":"","desc":["You gain resistance to acid and poison damage, and immunity to the poisoned condition. You can cast Greater Restoration and Heal once each per Long Rest without expending a spell slot."],"name":"Chemical Mastery","index":"chemical-mastery","level":15,"source":"Alchemist","effects":[{"type":"resistance","damage_type":"Acid"},{"type":"resistance","damage_type":"Poison"},{"type":"immunity","condition":"Poisoned"}]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'alchemist'),
       source = 'Eberron',
       migrated_at = now()
 where id = 'c418fe8b-72a5-4bfb-b538-4a6ed5f541e4';

