   set data = $persona_content_migration${"ui":{},"desc":["Daredevils with a reckless, flashy style, desperadoes excel at fighting with one-handed firearms, either singly or in pairs."],"name":"Desperado","class":{"url":"","name":"Gunslinger","index":"gunslinger"},"index":"desperado","source":"Gunslinger Bravado","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Gunslinger Archetype","subclass_level":3,"feature_details":[{"url":"","desc":["+4 bonus to damage and +2 bonus to attack rolls when wielding a single one-handed firearm."],"name":"Duelist Fighting Style","index":"duelist-fighting-style","level":3,"source":"Desperado","effects":[]},{"url":"","desc":["Bonus action to attack with off-hand firearm. Reload with full hands."],"name":"Two-Gun Fighting Style","index":"two-gun-fighting-style","level":3,"source":"Desperado","effects":[]},{"url":"","desc":["Expertise in Intimidation and Persuasion."],"name":"Unique Style","index":"unique-style","level":7,"source":"Desperado","effects":[{"type":"expertise_choice","count":2,"options":["Intimidation","Persuasion"],"category":"skill"}]},{"url":"","desc":["Action: Force a Wisdom save. On failure, target has disadvantage on attacks against you."],"name":"Taunt","index":"taunt-gs","level":13,"source":"Desperado","effects":[]},{"url":"","desc":["Draw and attack before anyone else rolls initiative."],"name":"Kill in the Blink of an Eye","index":"kill-in-the-blink","level":20,"source":"Desperado","effects":[]}]}$persona_content_migration$::jsonb,
