-- Life Domain (life)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing."],"name":"Life Domain","class":{"url":"","name":"Cleric","index":"cleric"},"index":"life","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Divine Domain","subclass_level":3,"feature_details":[{"url":"","desc":["When a spell you cast with a spell slot restores Hit Points, the creature regains additional Hit Points equal to 2 plus the spell slot’s level."],"name":"Disciple of Life","index":"disciple-of-life","level":3,"source":"Life Domain","effects":[]},{"url":"","desc":["You always have the following spells prepared: Aid, Bless, Cure Wounds, Lesser Restoration. At later levels: Mass Healing Word, Revivify (5th); Aura of Life, Death Ward (7th); Greater Restoration, Mass Cure Wounds (9th)."],"name":"Life Domain Spells","index":"life-domain-spells","level":3,"source":"Life Domain","effects":[{"type":"spell_access","level":1,"spell":"Bless","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":1,"spell":"Cure Wounds","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":2,"spell":"Aid","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":2,"spell":"Lesser Restoration","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":3,"spell":"Mass Healing Word","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":3,"spell":"Revivify","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":4,"spell":"Aura of Life","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":4,"spell":"Death Ward","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":5,"spell":"Greater Restoration","cast_free":true,"description":"Life Domain Spell"},{"type":"spell_access","level":5,"spell":"Mass Cure Wounds","cast_free":true,"description":"Life Domain Spell"}]},{"url":"","desc":["As a Magic action, you expend a use of your Channel Divinity to restore Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet and divide those HP among them (max half HP)."],"name":"Preserve Life","index":"preserve-life","level":3,"source":"Life Domain","effects":[]},{"url":"","desc":["Immediately after you cast a spell with a spell slot that restores HP to others, you regain HP equal to 2 plus the spell slot’s level."],"name":"Blessed Healer","index":"blessed-healer","level":6,"source":"Life Domain","effects":[]},{"url":"","desc":["When you roll dice to restore HP with a spell or Channel Divinity, use the highest number possible for each die."],"name":"Supreme Healing","index":"supreme-healing","level":17,"source":"Life Domain","effects":[]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'life'),
       source = 'Player''s Handbook 2024',
