update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The archetypal Champion focuses on the development of raw physical power."],"name":"Champion","class":{"url":"","name":"Fighter","index":"fighter"},"index":"champion","source":"Player's Handbook","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Martial Archetype","subclass_level":3,"feature_details":[{"url":"","desc":["Crit on 19-20."],"name":"Improved Critical","index":"improved-critical","level":3,"source":"Champion","effects":[{"name":"Improved Critical","type":"feature","description":"Critical hit range 19-20."}]},{"url":"","desc":["Add half prof bonus to Str/Dex/Con checks. Increase jump distance."],"name":"Remarkable Athlete","index":"remarkable-athlete","level":3,"source":"Champion","effects":[{"stat":"initiative","type":"stat_bonus","value":0}]},{"url":"","desc":["Choose a second Fighting Style."],"name":"Additional Fighting Style","index":"additional-fighting-style","level":7,"source":"Champion","effects":[{"name":"Additional Fighting Style","type":"feature_choice","count":1,"options":[{"desc":"You gain a +2 bonus to Attack Rolls you make with Ranged Weapons.","name":"Archery","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":2}]},{"desc":"While you are wearing armor, you gain a +1 bonus to AC.","name":"Defense","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.","name":"Dueling","effects":[{"stat":"weapon_damage","type":"stat_bonus","value":2}]},{"desc":"When you roll a 1 or 2 on a damage die for an attack you make with a melee weapon that you are wielding with two hands, you can reroll the die and must use the new roll.","name":"Great Weapon Fighting"},{"desc":"When a creature you can see attacks a target other than you that is within 5 feet of you, you can use your reaction to impose disadvantage on the attack roll. You must be wielding a shield.","name":"Protection"},{"desc":"When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.","name":"Two-Weapon Fighting"},{"desc":"As long as you are not wearing armor or using a shield, you have a swimming speed and a climbing speed equal to your normal speed, and you gain a +1 bonus to AC.","name":"Mariner","effects":[{"stat":"ac","type":"stat_bonus","value":1}]},{"desc":"You are trained in making ranged attacks at close quarters. When making a ranged attack while you are within 5 feet of a hostile creature, you do not have disadvantage on the attack roll. Your ranged attacks ignore half cover and three-quarter cover against targets within 30 feet of you. Finally, you have a +1 bonus to attack rolls on ranged attacks.","name":"Close Quarters Shooter","effects":[{"stat":"ranged_attack","type":"stat_bonus","value":1}]},{"desc":"When a teammate misses an opportunity attack against an enemy you can see, you can use your reaction to make an opportunity attack against the same target, as long as they are in range.","name":"Opportune Ranger"}]}]}]}$persona_content_migration$::jsonb,
