-- Warrior of the Open Hand (open-hand)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["Masters of martial arts combat, manipulating Focus to heal or harm. They excel in controlling the battlefield with their unarmed strikes."],"name":"Warrior of the Open Hand","class":{"url":"","name":"Monk","index":"monk"},"index":"open-hand","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Monastic Tradition","subclass_level":3,"feature_details":[{"url":"","desc":["Whenever you hit a creature with an unarmed strike granted by your Flurry of Blows, you can impose one of the following effects on that target:","**Addle:** The target can't make opportunity attacks until the start of your next turn.","**Push:** The target must succeed on a Strength saving throw or be pushed up to 15 feet away from you.","**Topple:** The target must succeed on a Dexterity saving throw or be knocked Prone."],"name":"Open Hand Technique","index":"open-hand-technique","level":3,"source":"Warrior of the Open Hand","effects":[]},{"url":"","desc":["You can tap into your inner reserves to heal yourself. As a bonus action, you can roll your Martial Arts die. You regain a number of HP equal to the roll plus your Wisdom modifier.","You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."],"name":"Wholeness of Body","index":"wholeness-of-body","level":6,"source":"Warrior of the Open Hand","effects":[{"name":"Wholeness of Body","type":"bonus_action","description":"As a bonus action, you can roll your Martial Arts die. You regain a number of HP equal to the roll plus your Wisdom modifier."}]},{"url":"","desc":["Your Step of the Wind is so instinctive that you can use it with ease. Whenever you use a Bonus Action that isn't Step of the Wind, you can also use Step of the Wind as part of that Bonus Action."],"name":"Fleet Step","index":"fleet-step","level":11,"source":"Warrior of the Open Hand","effects":[]},{"url":"","desc":["You gain the ability to set up lethal vibrations in someone's body. When you hit a creature with an unarmed strike, you can spend 4 Focus Points to start these vibrations, which last for a number of days equal to your Monk level. The vibrations are harmless unless you use your action to end them. To do so, you and the target must be on the same plane of existence.","When you use this action, the target must make a Constitution saving throw. On a failed save, the target takes 10d12 Force damage. On a successful save, the target takes half as much damage."],"name":"Quivering Palm","index":"quivering-palm","level":17,"source":"Warrior of the Open Hand","effects":[{"name":"Quivering Palm (End Vibrations)","type":"action","description":"Deal 10d12 Force damage (Con save for half)."}]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'open-hand'),
       source = 'Player''s Handbook 2024',
       migrated_at = now()
 where id = 'e092bf57-30f3-42f8-be2a-fdf1e7435af0';

