-- Warrior of Mercy (mercy)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["Monks who manipulate the life force of others to bring aid or end suffering, often wearing masks to represent their dual nature."],"name":"Warrior of Mercy","class":{"url":"","name":"Monk","index":"monk"},"index":"mercy","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Monastic Tradition","subclass_level":3,"feature_details":[{"url":"","desc":["You gain proficiency in the Insight and Medicine skills, and you gain proficiency with the herbalism kit."],"name":"Implements of Mercy","index":"implements-of-mercy","level":3,"source":"Warrior of Mercy","effects":[{"type":"proficiency","target":"Insight","category":"skill"},{"type":"proficiency","target":"Medicine","category":"skill"},{"type":"proficiency","target":"Herbalism Kit","category":"tool"}]},{"url":"","desc":["As an action, you can spend 1 Focus Point to touch a creature and restore HP equal to a roll of your Martial Arts die + your Wisdom modifier.","When you use Flurry of Blows, you can replace one of the unarmed strikes with a use of this feature without spending a Focus Point for the healing."],"name":"Hand of Healing","index":"hand-of-healing-2024","level":3,"source":"Warrior of Mercy","effects":[{"name":"Hand of Healing","type":"action","description":"As an action, you can spend 1 Focus Point to touch a creature and restore HP equal to a roll of your Martial Arts die + your Wisdom modifier. When you use Flurry of Blows, you can replace one of the unarmed strikes with a use of this feature without spending a Focus Point for the healing."}]},{"url":"","desc":["Once per turn when you hit a creature with an unarmed strike, you can spend 1 Focus Point to deal extra Necrotic damage equal to a roll of your Martial Arts die + your Wisdom modifier."],"name":"Hand of Harm","index":"hand-of-harm-2024","level":3,"source":"Warrior of Mercy","effects":[]},{"url":"","desc":["Your Hand of Healing can now also remove one of the following conditions: Blinded, Deafened, Paralyzed, Poisoned, or Stunned.","When you use Hand of Harm, you can also subject the target to the Poisoned condition until the end of your next turn."],"name":"Physician's Touch","index":"physicians-touch","level":6,"source":"Warrior of Mercy","effects":[]},{"url":"","desc":["When you use Flurry of Blows, you can replace both of the unarmed strikes with a use of Hand of Healing, or you can replace one with Hand of Healing and the other with Hand of Harm without spending additional Focus Points."],"name":"Flurry of Healing and Harm","index":"flurry-of-healing-and-harm","level":11,"source":"Warrior of Mercy","effects":[]},{"url":"","desc":["As an action, you can touch the corpse of a creature that died within the last 24 hours and spend 5 Focus Points. The creature returns to life with 0 HP and regains HP equal to 4d10 + your Wisdom modifier. Once you use this feature, you can't do so again until you finish a Long Rest."],"name":"Hand of Ultimate Mercy","index":"hand-of-ultimate-mercy","level":17,"source":"Warrior of Mercy","effects":[{"name":"Hand of Ultimate Mercy","type":"action","description":"As an action, you can touch the corpse of a creature that died within the last 24 hours and spend 5 Focus Points. The creature returns to life with 0 HP and regains HP equal to 4d10 + your Wisdom modifier. Once you use this feature, you can't do so again until you finish a Long Rest."}]}]}$persona_content_migration$::jsonb,
