-- Warrior of Shadow (shadow)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["Ninjas and assassins who manipulate darkness to strike from the shadows."],"name":"Warrior of Shadow","class":{"url":"","name":"Monk","index":"monk"},"index":"shadow","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Monastic Tradition","subclass_level":3,"feature_details":[{"url":"","desc":["You learn the Minor Illusion cantrip, using Wisdom as your spellcasting ability.","You can also spend 1 Focus Point to cast Darkness, Darkvision, Pass Without Trace, or Silence without material components. When you cast Darkness this way, you can move it at the start of each of your turns."],"name":"Shadow Arts","index":"shadow-arts-2024","level":3,"source":"Warrior of Shadow","effects":[{"type":"spell_access","spell":"Minor Illusion","cast_free":true}]},{"url":"","desc":["As a bonus action, you can magically teleport up to 60 feet to an unoccupied space you can see that is in dim light or darkness. You then have advantage on the next melee attack roll you make before the end of the current turn."],"name":"Shadow Step","index":"shadow-step-2024","level":6,"source":"Warrior of Shadow","effects":[{"name":"Shadow Step","type":"bonus_action","description":"As a bonus action, you can magically teleport up to 60 feet to an unoccupied space you can see that is in dim light or darkness. You then have advantage on the next melee attack roll you make before the end of the current turn."}]},{"url":"","desc":["You can see through the darkness created by your Shadow Arts Darkness spell."],"name":"Improved Shadow Arts","index":"improved-shadow-arts","level":11,"source":"Warrior of Shadow","effects":[]},{"url":"","desc":["While you are in dim light or darkness, you can use a bonus action to become Invisible. You remain Invisible until you make an attack roll, cast a spell, or enter an area of bright light."],"name":"Cloak of Shadows","index":"cloak-of-shadows-2024","level":17,"source":"Warrior of Shadow","effects":[{"name":"Cloak of Shadows","type":"bonus_action","description":"While you are in dim light or darkness, you can use a bonus action to become Invisible. You remain Invisible until you make an attack roll, cast a spell, or enter an area of bright light."}]}]}$persona_content_migration$::jsonb,
