   set data = $persona_content_migration${"ui":{},"desc":["Your innate magic comes from draconic magic that was mingled with your blood or that of your ancestors."],"name":"Draconic Bloodline","class":{"url":"","name":"Sorcerer","index":"sorcerer"},"index":"draconic-bloodline","source":"Player's Handbook","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Sorcerous Origin","subclass_level":3,"feature_details":[{"url":"","desc":["You choose one type of dragon as your ancestor. The damage type associated with each dragon is used by features you gain later."],"name":"Dragon Ancestor","index":"dragon-ancestor","level":1,"source":"Draconic Bloodline","effects":[]},{"url":"","desc":["Your HP maximum increases by 1 at 1st level and by 1 whenever you gain a level in this class. Additionally, your AC equals 13 + your Dexterity modifier when you aren't wearing armor."],"name":"Draconic Resilience","index":"draconic-resilience","level":1,"source":"Draconic Bloodline","effects":[{"stat":"hp_per_level","type":"stat_bonus","value":1}]},{"url":"","desc":["When you cast a spell that deals damage of the type associated with your draconic ancestry, you can add your Charisma modifier to one damage roll of that spell. You can also spend 1 sorcery point to gain resistance to that damage type for 1 hour."],"name":"Elemental Affinity","index":"elemental-affinity","level":6,"source":"Draconic Bloodline","effects":[]}]}$persona_content_migration$::jsonb,
