-- Clockwork Soul (clockwork-soul)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The cosmic force of order has suffused your being with magic."],"name":"Clockwork Soul","class":{"url":"","name":"Sorcerer","index":"sorcerer"},"index":"clockwork-soul","source":"Tasha's Cauldron of Everything","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Sorcerous Origin","subclass_level":3,"feature_details":[{"url":"","desc":["You learn additional spells when you reach certain levels in this class. These spells don't count against the number of sorcerer spells you know."],"name":"Clockwork Spells","index":"clockwork-spells","level":1,"source":"Clockwork Soul","effects":[]},{"url":"","desc":["Your connection to the plane of absolute order allows you to equalize chaotic moments. When a creature you can see within 60 feet of you is about to roll a d20 with advantage or disadvantage, you can use your reaction to prevent the roll from being affected by advantage or disadvantage. (PB/Long Rest)"],"name":"Restore Balance","index":"restore-balance","level":1,"source":"Clockwork Soul","effects":[]},{"url":"","desc":["You can tap into the grand equation of existence to create a shimmering shield of order around yourself or another creature. As an action, you can expend 1 to 5 sorcery points to create a magical ward around yourself or another creature you can see within 30 feet of you. The ward lasts until you finish a long rest or until you use this feature again."],"name":"Bastion of Law","index":"bastion-of-law","level":6,"source":"Clockwork Soul","effects":[]}]}$persona_content_migration$::jsonb,
