   set data = $persona_content_migration${"ui":{},"desc":["Your innate magic comes from the power of elemental air."],"name":"Storm Sorcery","class":{"url":"","name":"Sorcerer","index":"sorcerer"},"index":"storm-sorcery","source":"Xanathar's Guide to Everything","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Sorcerous Origin","subclass_level":3,"feature_details":[{"url":"","desc":["You can speak, read, and write Primordial. Knowing this language allows you to understand and be understood by those who speak its dialects: Aquan, Auran, Ignan, and Terran."],"name":"Wind Speaker","index":"wind-speaker","level":1,"source":"Storm Sorcery","effects":[{"type":"proficiency_choice","count":1,"options":["Primordial"],"category":"language"}]},{"url":"","desc":["Immediately before or after you cast a spell of 1st level or higher, you can use a bonus action to cause whirling gusts of elemental air to briefly surround you, allowing you to fly up to 10 feet without provoking opportunity attacks."],"name":"Tempestuous Magic","index":"tempestuous-magic","level":1,"source":"Storm Sorcery","effects":[]},{"url":"","desc":["You gain resistance to lightning and thunder damage. In addition, whenever you start casting a spell of 1st level or higher that deals lightning or thunder damage, stormy magic escapes from you, dealing lightning or thunder damage to creatures of your choice within 10 feet of you."],"name":"Heart of the Storm","index":"heart-of-the-storm","level":6,"source":"Storm Sorcery","effects":[{"type":"resistance","damage_type":"Lightning"},{"type":"resistance","damage_type":"Thunder"}]}]}$persona_content_migration$::jsonb,
