update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["You have made your pact with a mysterious entity from the Shadowfell—a force that manifests in sentient magic weapons carved from the stuff of shadow."],"name":"The Hexblade","class":{"url":"","name":"Warlock","index":"warlock"},"index":"the-hexblade","source":"Xanathar's Guide to Everything","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Otherworldly Patron","subclass_level":3,"feature_details":[{"url":"","desc":["As a bonus action, choose one creature you can see within 30 feet of you. The target is cursed for 1 minute. You gain a bonus to damage rolls against the cursed target equal to your proficiency bonus. Any attack roll you make against the cursed target is a critical hit on a roll of 19 or 20. If the cursed target dies, you regain HP equal to your warlock level + your Charisma modifier (minimum of 1). (1/Short or Long Rest)"],"name":"Hexblade's Curse","index":"hexblades-curse","level":1,"source":"The Hexblade","effects":[]},{"url":"","desc":["You gain proficiency with medium armor, shields, and martial weapons. When you attack with a weapon that you are proficient with and that lacks the two-handed property, you can use your Charisma modifier, instead of Strength or Dexterity, for the attack and damage rolls."],"name":"Hex Warrior","index":"hex-warrior","level":1,"source":"The Hexblade","effects":[{"type":"proficiency","target":"Medium Armor","category":"armor"},{"type":"proficiency","target":"Shields","category":"armor"},{"type":"proficiency","target":"Martial Weapons","category":"weapon"}]},{"url":"","desc":["When you slay a humanoid, you can cause its spirit to rise from its corpse as a specter. When the specter appears, it gains temporary HP equal to half your warlock level. Roll initiative for the specter, which has its own turns. It obeys your verbal commands, and it gains a special bonus to its attack rolls equal to your Charisma modifier (minimum of +0). (1/Long Rest)"],"name":"Accursed Specter","index":"accursed-specter","level":6,"source":"The Hexblade","effects":[]}]}$persona_content_migration$::jsonb,
