   set data = $persona_content_migration${"ui":{},"desc":["An more offensive path, your spells will do lots of damage, but you will lose support potential."],"name":"Destiny Caster","class":{"url":"","name":"Card Master","index":"card-master"},"index":"destiny-caster","source":"Card Master Path","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Path","subclass_level":4,"feature_details":[{"url":"","desc":["When you cast a spell, you can opt to spend 10 feet of movement to put the spell inside a damage booster special card to obtain the following effects: The spell DC is increased by your proficiency. The spell damage dice are increased by 6. If you have to roll an attack for the spell you do not have to, all your spells cards only need a saving throw of Charisma to take half of the damage. Your spells area gain your Charisma multiplied by your arcana ability of area of effect."],"name":"Spell Cards","index":"spell-cards","level":4,"source":"Destiny Caster","effects":[]},{"url":"","desc":["The Devil extra dice are increased by your Charisma and your Intelligence now. You can pick the Devil card without having to spend 1 choice point as a free action one time per long rest."],"name":"More Powerful Card","index":"more-powerful-card","level":8,"source":"Destiny Caster","effects":[{"name":"Free Devil Card","type":"feature","description":"Pick the Devil card as a free action 1/long rest without spending choice points."}]},{"url":"","desc":["When you sacrifice an activated card to make a Fool Stack, you can cast a spell without spending a spell slot. The Fool Spell damage is now maximized."],"name":"The Powerfool","index":"the-powerfool","level":12,"source":"Destiny Caster","effects":[]},{"url":"","desc":["When you use Spell Cards you deal maximum damage. If the enemy rolls a 1 in the saving throw of your card, the damage is tripled."],"name":"Sharp Cards","index":"sharp-cards","level":16,"source":"Destiny Caster","effects":[]}]}$persona_content_migration