   set data = $persona_content_migration${"ui":{},"desc":["The Order of the Lycan is a proud and ancient order of blood hunters who have embraced the curse of lycanthropy, using it as a weapon against the darkness. These hunters can transform into a hybrid form, gaining incredible strength and resilience."],"name":"Order of the Lycan","class":{"url":"","name":"Blood Hunter","index":"blood-hunter"},"index":"lycan","source":"Blood Hunter Order","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Blood Hunter Order","subclass_level":3,"feature_details":[{"url":"","desc":["You gain advantage on Wisdom (Perception) checks that rely on hearing or smell."],"name":"Heightened Senses","index":"heightened-senses","level":3,"source":"Lycan","effects":[]},{"url":"","desc":["As a bonus action, you can transform into a hybrid form for up to 1 hour. While in this form, you gain a bonus to melee damage rolls, resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks that aren't silvered, and your AC increases by 1. You also gain the Feral Might and Resilient Hide features."],"name":"Hybrid Transformation","index":"hybrid-transformation","level":3,"source":"Lycan","effects":[]},{"url":"","desc":["Your speed increases by 10 feet. You also gain a bonus to your jump distance equal to your Strength score."],"name":"Stalker's Prowess","index":"stalkers-prowess","level":7,"source":"Lycan","effects":[]},{"url":"","desc":["You can now use your Hybrid Transformation twice between rests. Additionally, your hybrid form's bonuses increase."],"name":"Advanced Transformation","index":"advanced-transformation","level":11,"source":"Lycan","effects":[]},{"url":"","desc":["You can use your reaction to make a melee attack against a creature that misses you with a melee attack."],"name":"Iron Volley","index":"iron-volley","level":15,"source":"Lycan","effects":[]},{"url":"","desc":["You can now use your Hybrid Transformation an unlimited number of times. Additionally, you gain the Bloodlust feature."],"name":"Hybrid Transformation Mastery","index":"hybrid-transformation-mastery","level":18,"source":"Lycan","effects":[]}]}$persona_content_migration$::jsonb,
