   set data = $persona_content_migration${"ui":{},"desc":["Monks who channel the raw power of the elements through their martial arts."],"name":"Warrior of the Elements","class":{"url":"","name":"Monk","index":"monk"},"index":"four-elements","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Monastic Tradition","subclass_level":3,"feature_details":[{"url":"","desc":["At the start of your turn, you can spend 1 Focus Point to imbue yourself with elemental energy for 10 minutes. While active:","**Reach:** Your reach with unarmed strikes increases by 10 feet.","**Elemental Damage:** Your unarmed strikes can deal Acid, Cold, Fire, or Lightning damage instead of their normal damage type.","**Push/Pull:** When you hit with an unarmed strike, you can force the target to make a Strength save or be pushed or pulled 10 feet."],"name":"Elemental Attunement","index":"elemental-attunement","level":3,"source":"Warrior of the Elements","effects":[]},{"url":"","desc":["While your Elemental Attunement is active, you gain the following benefits:","**Resistance:** You gain resistance to one of the following damage types: Acid, Cold, Fire, or Lightning.","**Stride of the Elements:** When you use Step of the Wind, you gain a Fly speed and Swim speed equal to your speed for the turn.","**Elemental Damage:** Once on each of your turns when you deal damage with an unarmed strike, you can deal an extra 1d6 damage of the chosen type."],"name":"Elemental Epitome","index":"elemental-epitome","level":6,"source":"Warrior of the Elements","effects":[]},{"url":"","desc":["As an action, you can spend 2 Focus Points to create a 20-foot-radius sphere of elemental energy centered on yourself. Each creature in the area must make a Dexterity save or take damage equal to three rolls of your Martial Arts die. You can also teleport to an unoccupied space within the area as part of this action."],"name":"Environmental Burst","index":"environmental-burst","level":11,"source":"Warrior of the Elements","effects":[{"name":"Environmental Burst","type":"action","description":"Spend 2 Focus Points for 20ft elemental burst damage + teleport."}]},{"url":"","desc":["While your Elemental Attunement is active, you have resistance to Acid, Cold, Fire, and Lightning damage. Also, when you use Flurry of Blows, you can replace one of the attacks with an Environmental Burst without spending additional Focus Points."],"name":"Elemental Perfection","index":"elemental-perfection","level":17,"source":"Warrior of the Elements","effects":[]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'four-elements'),
       source = 'Player''s Handbook 2024',
       migrated_at = now()
 where id = '0fd437c7-ac70-49c7-a8c9-1421a4bce2af';

