-- Order of the Ghostslayer (ghostslayer)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The Order of the Ghostslayer is the oldest and most traditional of the orders, having its roots in the very first blood hunters. These hunters seek out and destroy the undead, using their own life force to fuel their strikes."],"name":"Order of the Ghostslayer","class":{"url":"","name":"Blood Hunter","index":"blood-hunter"},"index":"ghostslayer","source":"Blood Hunter Order","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Blood Hunter Order","subclass_level":3,"feature_details":[{"url":"","desc":["You learn the Rite of the Dawn as a crimson rite. While this rite is active, your weapon deals radiant damage. Additionally, you shed bright light in a 20-foot radius and dim light for an additional 20 feet. Your attacks with this rite deal extra radiant damage to undead equal to your Wisdom modifier."],"name":"Rite of the Dawn","index":"rite-of-the-dawn","level":3,"source":"Ghostslayer","effects":[]},{"url":"","desc":["You gain an additional use of your Blood Maledict feature. Additionally, your blood curses can affect any creature, regardless of whether it has blood or not."],"name":"Curse Specialist","index":"curse-specialist","level":3,"source":"Ghostslayer","effects":[]},{"url":"","desc":["At the start of your turn, if you aren't incapacitated, you can magically step into the ethereal plane. You remain there until the end of your current turn. You can use this feature a number of times equal to your Intelligence modifier (min 1) per long rest."],"name":"Ethereal Step","index":"ethereal-step","level":7,"source":"Ghostslayer","effects":[]},{"url":"","desc":["Your Brand of Castigation now exposes a creature's vulnerabilities. Your Crimson Rite damage die is doubled against a branded creature."],"name":"Brand of Sundering","index":"brand-of-sundering","level":11,"source":"Ghostslayer","effects":[]},{"url":"","desc":["You learn the Blood Curse of the Exorcist. This does not count against your number of blood curses known."],"name":"Blood Curse of the Exorcist","index":"blood-curse-of-the-exorcist","level":15,"source":"Ghostslayer","effects":[]},{"url":"","desc":["Your Rite of the Dawn now deals even more damage to undead, and you can use it to protect your allies."],"name":"Rite of the Dawn (Improved)","index":"rite-of-the-dawn-improved","level":18,"source":"Ghostslayer","effects":[]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'ghostslayer'),
       source = 'Blood Hunter Order',
       migrated_at = now()
 where id = '72b00dc0-6113-4e3a-825e-53f0bffd682e';

-- Support Cards (support-cards)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["Focuses on supporting allies with powerful card effects and enhanced healing."],"name":"Support Cards","class":{"url":"","name":"Card Master","index":"card-master"},"index":"support-cards","source":"Card Master Path","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Path","subclass_level":4,"feature_details":[{"url":"","desc":["You can use pick a card twice in one bonus action. You can have 2 cards that buff allies stacking. Your maximum cards of the same duration is 3."],"name":"More Cards","index":"more-cards","level":4,"source":"Support Cards","effects":[{"name":"Pick a Card (x2)","type":"bonus_action","description":"Use Pick a Card twice in one bonus action."}]},{"url":"","desc":["The Cards The Star, The Moon and The Temperance now heal a number of d12 equivalent to your CHA + INT, and give allies a damage boost of the same amount. You have extra choice points equal to your CHA modifier."],"name":"Powerful Support","index":"powerful-support","level":8,"source":"Support Cards","effects":[{"name":"Powerful Support","type":"feature","description":"Star, Moon, Temperance boosted. Extra Choice Points = CHA mod."}]},{"url":"","desc":["You can use pick a card and transfer the card to another person. Your heal and buff dice are always maxed. The Fool spell damage now heals your allies."],"name":"Give Card","index":"give-card","level":12,"source":"Support Cards","effects":[{"name":"Give Card","type":"feature","description":"Transfer cards to others. Max heal/buff dice. Fool spell heals allies."}]},{"url":"","desc":["When you use the Moon, the Star or the Hermit, you increase the AC of your allies by your CHA + INT. Allies have 12d12 damage reduction if buffed. The heal of the Fool spell is doubled. When you buff an ally, they gain 1 extra attack. Max cards of same duration is 5."],"name":"Armored Allies","index":"armored-allies","level":16,"source":"Support Cards","effects":[{"name":"Armored Allies","type":"feature","description":"AC bonus = CHA+INT. 12d12 damage reduction. Doubled Fool spell heal. Extra attack for buffed allies."}]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'support-cards'),
       source = 'Card Master Path',
       migrated_at = now()
 where id = '8d6444c4-65c9-405e-83a6-a586cf5bd022';

-- College of Glamour (glamour)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The College of Glamour is the domain of bards who mastered their craft in the vibrant realm of the Feywild or under the tutelage of those who have dwelt there."],"name":"College of Glamour","class":{"url":"","name":"Bard","index":"bard"},"index":"glamour","source":"Xanathar's Guide to Everything","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Bard College","subclass_level":3,"feature_details":[{"url":"","desc":["As a bonus action, you can expend one use of your Bardic Inspiration to grant yourself a wondrous appearance. When you do so, choose a number of creatures you can see and who can see you within 60 feet of you, up to a number equal to your Charisma modifier (minimum of one). Each of them gains 5 temporary hit points."],"name":"Mantle of Inspiration","index":"mantle-of-inspiration","level":3,"source":"Glamour","effects":[]},{"url":"","desc":["If you perform for at least 1 minute, you can attempt to inspire wonder in your audience. At the end of the performance, choose a number of humanoids within 60 feet of you who watched and listened to all of it, up to a number equal to your Charisma modifier (minimum of one). Each target must succeed on a Wisdom saving throw against your spell save DC or be charmed by you."],"name":"Enthralling Performance","index":"enthralling-performance","level":3,"source":"Glamour","effects":[]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'glamour'),
       source = 'Xanathar''s Guide to Everything',
       migrated_at = now()
 where id = '90c1e79c-d033-4bb5-8e5c-bea190d95be4';

