-- Knowledge Domain (knowledge)
update public.custom_subclasses
   set data = $persona_content_migration${"ui":{},"desc":["The Knowledge Domain focuses on the accumulation of wisdom and discovery of secrets."],"name":"Knowledge Domain","class":{"url":"","name":"Cleric","index":"cleric"},"index":"knowledge","source":"Player's Handbook 2024","resources":[],"spell_list":[],"schema_version":2,"subclass_label":"Divine Domain","subclass_level":3,"feature_details":[{"url":"","desc":["You learn two languages of your choice. You also become proficient in two of the following skills of your choice: Arcana, History, Nature, or Religion. Your Proficiency Bonus is doubled for any ability check you make that uses either of those skills."],"name":"Blessings of Knowledge","index":"blessings-of-knowledge","level":3,"source":"Knowledge Domain","effects":[{"type":"proficiency_choice","count":2,"category":"language"},{"type":"expertise_choice","count":2,"options":["Arcana","History","Nature","Religion"],"category":"skill"}]},{"url":"","desc":["Prepared spells: Command, Identify, Augury, Suggestion. Later: Nondetection, Speak with Dead (5th); Arcane Eye, Confusion (7th); Legend Lore, Scrying (9th)."],"name":"Knowledge Domain Spells","index":"knowledge-domain-spells","level":3,"source":"Knowledge Domain","effects":[{"type":"spell_access","level":1,"spell":"Command","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":1,"spell":"Identify","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":2,"spell":"Augury","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":2,"spell":"Suggestion","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":3,"spell":"Nondetection","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":3,"spell":"Speak with Dead","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":4,"spell":"Arcane Eye","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":4,"spell":"Confusion","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":5,"spell":"Legend Lore","cast_free":true,"description":"Knowledge Domain Spell"},{"type":"spell_access","level":5,"spell":"Scrying","cast_free":true,"description":"Knowledge Domain Spell"}]},{"url":"","desc":["As a Magic action, you can expend a use of your Channel Divinity to gain Proficiency in one skill or tool of your choice. This proficiency lasts for 10 minutes."],"name":"Channel Divinity: Knowledge of the Ages","index":"knowledge-of-the-ages","level":3,"source":"Knowledge Domain","effects":[]},{"url":"","desc":["As a Magic action, you can expend a use of your Channel Divinity to read the surface thoughts of a creature within 60 feet. While you are reading its thoughts, you can use a Magic action to cast Suggestion on the creature without expending a spell slot or providing material components. The creature automatically fails its saving throw."],"name":"Read Thoughts","index":"read-thoughts","level":6,"source":"Knowledge Domain","effects":[]},{"url":"","desc":["You can call up visions of the past by meditating. You can spend 1 minute or more in meditation and prayer to receive a vision of either an object's history or an area's history. This meditation can last up to 10 minutes per Cleric level."],"name":"Visions of the Past","index":"visions-of-the-past","level":17,"source":"Knowledge Domain","effects":[]}]}$persona_content_migration$::jsonb,
